export const ddkSentences: Sentence[] = [
  {"id":"snt_ch_work_ddk_1_1","chapterId":"ch_work_ddk_1","textTraditional":"道可道，非常道。名可名，非常名。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"đạo khả đạo， phi thường đạo。 danh khả danh， phi thường danh。","pinyinReading":"dào kě dào， fēi cháng dào。 míng kě míng， fēi cháng míng。","translation":"Đạo mà có thể nói ra được thì không phải Đạo vĩnh hằng. Tên mà có thể gọi ra được thì không phải tên vĩnh hằng.","textSimplified":"道可道，非常道。名可名，非常名。"},
  {"id":"snt_ch_work_ddk_1_2","chapterId":"ch_work_ddk_1","textTraditional":"無名天地之始，有名萬物之母。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"vô danh thiên địa chi thủy， hữu danh vạn vật chi mẫu。","pinyinReading":"wú míng tiān dì zhī shǐ， yǒu míng wàn wù zhī mǔ。","translation":"Không tên là khởi đầu của trời đất, có tên là mẹ của muôn vật.","textSimplified":"无名天地之始，有名万物之母。"},
  {"id":"snt_ch_work_ddk_1_3","chapterId":"ch_work_ddk_1","textTraditional":"故常無欲以觀其妙，常有欲以觀其徼。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"cố thường vô dục dĩ quan kỳ diệu， thường hữu dục dĩ quan kỳ kiếu。","pinyinReading":"gù cháng wú yù yǐ guān qí miào， cháng yǒu yù yǐ guān qí jiào。","translation":"Cho nên thường không có ham muốn để thấy sự huyền diệu; thường có ham muốn để thấy chỗ quy kết.","textSimplified":"故常无欲以观其妙，常有欲以观其徼。"},
  {"id":"snt_ch_work_ddk_1_4","chapterId":"ch_work_ddk_1","textTraditional":"此兩者同出而異名，同謂之玄。玄之又玄，衆妙之門。","sentenceOrder":4,"paragraphGroup":2,"hanVietReading":"thử lưỡng giả đồng xuất nhi dị danh， đồng vị chi huyền。 huyền chi hựu huyền， chúng diệu chi môn。","pinyinReading":"cǐ liǎng zhě tóng chū ér yì míng， tóng wèi zhī xuán。 xuán zhī yòu xuán， zhòng miào zhī mén。","translation":"Hai điều ấy cùng nguồn gốc mà khác tên, đều gọi là Huyền. Huyền rồi lại huyền, cửa của mọi huyền diệu.","textSimplified":"此两者同出而异名，同谓之玄。玄之又玄，众妙之门。"},

  {"id":"snt_ch_work_ddk_2_1","chapterId":"ch_work_ddk_2","textTraditional":"天下皆知美之為美，斯惡已；皆知善之為善，斯不善已。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thiên hạ giai tri mỹ chi vi mỹ， tư ác dĩ； giai tri thiện chi vi thiện， tư bất thiện dĩ。","pinyinReading":"tiān xià jiē zhī měi zhī wéi měi， sī è yǐ； jiē zhī shàn zhī wéi shàn， sī bù shàn yǐ。","translation":"Thiên hạ đều biết đẹp là đẹp, ấy là có xấu rồi; đều biết thiện là thiện, ấy là có bất thiện rồi.","textSimplified":"天下皆知美之为美，斯恶已；皆知善之为善，斯不善已。"},
  {"id":"snt_ch_work_ddk_2_2","chapterId":"ch_work_ddk_2","textTraditional":"有無相生，難易相成，長短相形，高下相盈，音聲相和，前後相隨，恆也。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"hữu vô tương sinh， nan dị tương thành， trường đoản tương hình， cao hạ tương doanh， âm thanh tương hòa， tiền hậu tương tùy， hằng dã。","pinyinReading":"yǒu wú xiāng shēng， nán yì xiāng chéng， cháng duǎn xiāng xíng， gāo xià xiāng yíng， yīn shēng xiāng hè， qián hòu xiāng suí， héng yě。","translation":"Có và không sinh ra nhau, khó và dễ thành tựu nhau, dài và ngắn so sánh nhau, cao và thấp dựa vào nhau, âm và thanh hòa hợp nhau, trước và sau theo nhau — đó là lẽ thường.","textSimplified":"有无相生，难易相成，长短相形，高下相盈，音声相和，前后相随，恒也。"},
  {"id":"snt_ch_work_ddk_2_3","chapterId":"ch_work_ddk_2","textTraditional":"是以聖人處無為之事，行不言之教。萬物作而弗始，生而弗有，為而弗恃，功成而弗居。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"thị dĩ thánh nhân xử vô vi chi sự， hành bất ngôn chi giáo。 vạn vật tác nhi phất thủy， sinh nhi phất hữu， vi nhi phất thị， công thành nhi phất cư。","pinyinReading":"shì yǐ shèng rén chǔ wú wéi zhī shì， xíng bù yán zhī jiào。 wàn wù zuò ér fú shǐ， shēng ér fú yǒu， wéi ér fú shì， gōng chéng ér fú jū。","translation":"Vì thế thánh nhân xử sự bằng vô vi, thi hành giáo hóa không lời. Muôn vật dấy lên mà không khởi đầu, sinh ra mà không chiếm hữu, làm mà không cậy nhờ, công thành mà không ở lại.","textSimplified":"是以圣人处无为之事，行不言之教。万物作而弗始，生而弗有，为而弗恃，功成而弗居。"},
  {"id":"snt_ch_work_ddk_2_4","chapterId":"ch_work_ddk_2","textTraditional":"夫唯弗居，是以不去。","sentenceOrder":4,"paragraphGroup":2,"hanVietReading":"phù duy phất cư， thị dĩ bất khứ。","pinyinReading":"fú wéi fú jū， shì yǐ bù qù。","translation":"Chính vì không ở lại, nên không mất đi."},

  {"id":"snt_ch_work_ddk_3_1","chapterId":"ch_work_ddk_3","textTraditional":"不尚賢，使民不爭；不貴難得之貨，使民不為盜；不見可欲，使民心不亂。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"bất thượng hiền， sử dân bất tranh； bất quý nan đắc chi hóa， sử dân bất vi đạo； bất kiến khả dục， sử dân tâm bất loạn。","pinyinReading":"bù shàng xián， shǐ mín bù zhēng； bù guì nán dé zhī huò， shǐ mín bù wéi dào； bù xiàn kě yù， shǐ mín xīn bù luàn。","translation":"Không tôn sùng người hiền, khiến dân không tranh đua; không quý của khó được, khiến dân không trộm cắp; không phô bày cái đáng ham muốn, khiến lòng dân không loạn.","textSimplified":"不尚贤，使民不争；不贵难得之货，使民不为盗；不见可欲，使民心不乱。"},
  {"id":"snt_ch_work_ddk_3_2","chapterId":"ch_work_ddk_3","textTraditional":"是以聖人之治，虛其心，實其腹，弱其志，強其骨。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thị dĩ thánh nhân chi trị， hư kỳ tâm， thực kỳ phúc， nhược kỳ chí， cường kỳ cốt。","pinyinReading":"shì yǐ shèng rén zhī zhì， xū qí xīn， shí qí fù， ruò qí zhì， qiáng qí gǔ。","translation":"Vì thế phép trị của thánh nhân: làm trống lòng ham muốn, làm no bụng, làm yếu chí tranh đua, làm mạnh xương cốt.","textSimplified":"是以圣人之治，虚其心，实其腹，弱其志，强其骨。"},
  {"id":"snt_ch_work_ddk_3_3","chapterId":"ch_work_ddk_3","textTraditional":"常使民無知無欲，使夫智者不敢為也。為無為，則無不治。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"thường sử dân vô tri vô dục， sử phù trí giả bất cảm vi dã。 vi vô vi， tắc vô bất trị。","pinyinReading":"cháng shǐ mín wú zhī wú yù， shǐ fú zhì zhě bù gǎn wéi yě。 wéi wú wéi， zé wú bù zhì。","translation":"Khiến dân luôn không tham biết, không ham muốn, khiến kẻ mưu trí không dám làm. Làm theo vô vi, thì không gì là không yên trị.","textSimplified":"常使民无知无欲，使夫智者不敢为也。为无为，则无不治。"},

  {"id":"snt_ch_work_ddk_4_1","chapterId":"ch_work_ddk_4","textTraditional":"道沖而用之或不盈。淵兮似萬物之宗。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"đạo xung nhi dụng chi hoặc bất doanh。 uyên hề tự vạn vật chi tông。","pinyinReading":"dào chōng ér yòng zhī huò bù yíng。 yuān xī sì wàn wù zhī zōng。","translation":"Đạo rỗng không mà dùng thì dường như không bao giờ đầy. Sâu thẳm thay, dường như tổ tông của muôn vật.","textSimplified":"道冲而用之或不盈。渊兮似万物之宗。"},
  {"id":"snt_ch_work_ddk_4_2","chapterId":"ch_work_ddk_4","textTraditional":"挫其銳，解其紛，和其光，同其塵。湛兮似或存。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"tỏa kỳ duệ， giải kỳ phân， hòa kỳ quang， đồng kỳ trần。 trạm hề tự hoặc tồn。","pinyinReading":"cuò qí ruì， jiě qí fēn， hé qí guāng， tóng qí chén。 zhàn xī sì huò cún。","translation":"Bẻ bớt sắc bén, gỡ rối rắm, hòa ánh sáng, hợp cùng bụi trần. Lặng lẽ thay, dường như tồn tại.","textSimplified":"挫其锐，解其纷，和其光，同其尘。湛兮似或存。"},
  {"id":"snt_ch_work_ddk_4_3","chapterId":"ch_work_ddk_4","textTraditional":"吾不知誰之子，象帝之先。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"ngô bất tri thùy chi tử， tượng đế chi tiên。","pinyinReading":"wú bù zhī shuí zhī zǐ， xiàng dì zhī xiān。","translation":"Ta không biết nó là con ai, hình như có trước cả Thượng Đế."},

  {"id":"snt_ch_work_ddk_5_1","chapterId":"ch_work_ddk_5","textTraditional":"天地不仁，以萬物為芻狗；聖人不仁，以百姓為芻狗。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thiên địa bất nhân， dĩ vạn vật vi sô cẩu； thánh nhân bất nhân， dĩ bách tính vi sô cẩu。","pinyinReading":"tiān dì bù rén， yǐ wàn wù wéi chú gǒu； shèng rén bù rén， yǐ bǎi xìng wéi chú gǒu。","translation":"Trời đất bất nhân, coi muôn vật như chó rơm; thánh nhân bất nhân, coi trăm họ như chó rơm.","textSimplified":"天地不仁，以万物为刍狗；圣人不仁，以百姓为刍狗。"},
  {"id":"snt_ch_work_ddk_5_2","chapterId":"ch_work_ddk_5","textTraditional":"天地之間，其猶橐籥乎？虛而不屈，動而愈出。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"thiên địa chi gian， kỳ do thác thược hồ？ hư nhi bất khuất， động nhi dũ xuất。","pinyinReading":"tiān dì zhī jiān， qí yóu tuó yuè hū？ xū ér bù qū， dòng ér yù chū。","translation":"Khoảng giữa trời đất, chẳng phải như ống bễ lò sao? Rỗng mà không kiệt, càng động càng sinh ra.","textSimplified":"天地之间，其犹橐籥乎？虚而不屈，动而愈出。"},
  {"id":"snt_ch_work_ddk_5_3","chapterId":"ch_work_ddk_5","textTraditional":"多言數窮，不如守中。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"đa ngôn sác cùng， bất như thủ trung。","pinyinReading":"duō yán shuò qióng， bù rú shǒu zhōng。","translation":"Nói nhiều thì hay cùng kiệt, chẳng bằng giữ sự trống rỗng bên trong."},

  {"id":"snt_ch_work_ddk_6_1","chapterId":"ch_work_ddk_6","textTraditional":"谷神不死，是謂玄牝。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"cốc thần bất tử， thị vị huyền tẫn。","pinyinReading":"gǔ shén bù sǐ， shì wèi xuán pìn。","translation":"Thần của hang sâu không chết, gọi đó là Huyền Tẫn (giống cái huyền diệu).","textSimplified":"谷神不死，是谓玄牝。"},
  {"id":"snt_ch_work_ddk_6_2","chapterId":"ch_work_ddk_6","textTraditional":"玄牝之門，是謂天地根。綿綿若存，用之不勤。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"huyền tẫn chi môn， thị vị thiên địa căn。 miên miên nhược tồn， dụng chi bất cần。","pinyinReading":"xuán pìn zhī mén， shì wèi tiān dì gēn。 mián mián ruò cún， yòng zhī bù qín。","translation":"Cửa của Huyền Tẫn gọi là gốc rễ trời đất. Dằng dặc như còn mãi, dùng hoài không hết.","textSimplified":"玄牝之门，是谓天地根。绵绵若存，用之不勤。"},

  {"id":"snt_ch_work_ddk_7_1","chapterId":"ch_work_ddk_7","textTraditional":"天長地久。天地所以能長且久者，以其不自生，故能長生。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thiên trường địa cửu。 thiên địa sở dĩ năng trường thả cửu giả， dĩ kỳ bất tự sinh， cố năng trường sinh。","pinyinReading":"tiān cháng dì jiǔ。 tiān dì suǒ yǐ néng cháng qiě jiǔ zhě， yǐ qí bù zì shēng， gù néng cháng shēng。","translation":"Trời dài đất lâu. Trời đất sở dĩ dài lâu được là vì không sống cho mình, nên mới trường tồn.","textSimplified":"天长地久。天地所以能长且久者，以其不自生，故能长生。"},
  {"id":"snt_ch_work_ddk_7_2","chapterId":"ch_work_ddk_7","textTraditional":"是以聖人後其身而身先，外其身而身存。非以其無私邪？故能成其私。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thị dĩ thánh nhân hậu kỳ thân nhi thân tiên， ngoại kỳ thân nhi thân tồn。 phi dĩ kỳ vô tư tà？ cố năng thành kỳ tư。","pinyinReading":"shì yǐ shèng rén hòu qí shēn ér shēn xiān， wài qí shēn ér shēn cún。 fēi yǐ qí wú sī yé？ gù néng chéng qí sī。","translation":"Vì thế thánh nhân đặt mình sau mà lại được ở trước, gạt mình ra ngoài mà lại được bảo toàn. Chẳng phải vì không tư lợi sao? Nên mới thành được việc riêng.","textSimplified":"是以圣人后其身而身先，外其身而身存。非以其无私邪？故能成其私。"},

  {"id":"snt_ch_work_ddk_8_1","chapterId":"ch_work_ddk_8","textTraditional":"上善若水。水善利萬物而不爭，處衆人之所惡，故幾於道。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thượng thiện nhược thủy。 thủy thiện lợi vạn vật nhi bất tranh， xử chúng nhân chi sở ố， cố cơ ư đạo。","pinyinReading":"shàng shàn ruò shuǐ。 shuǐ shàn lì wàn wù ér bù zhēng， chǔ zhòng rén zhī suǒ wù， gù jī yú dào。","translation":"Điều thiện cao nhất giống như nước. Nước khéo làm lợi muôn vật mà không tranh giành, ở chỗ mọi người chê ghét, nên gần với Đạo.","textSimplified":"上善若水。水善利万物而不争，处众人之所恶，故几于道。"},
  {"id":"snt_ch_work_ddk_8_2","chapterId":"ch_work_ddk_8","textTraditional":"居善地，心善淵，與善仁，言善信，正善治，事善能，動善時。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"cư thiện địa， tâm thiện uyên， dữ thiện nhân， ngôn thiện tín， chính thiện trị， sự thiện năng， động thiện thời。","pinyinReading":"jū shàn dì， xīn shàn yuān， yǔ shàn rén， yán shàn xìn， zhèng shàn zhì， shì shàn néng， dòng shàn shí。","translation":"Ở chọn nơi lành, lòng sâu như vực, cho thì nhân ái, nói thì giữ tín, trị thì giỏi giang, làm thì tài năng, động thì hợp thời.","textSimplified":"居善地，心善渊，与善仁，言善信，正善治，事善能，动善时。"},
  {"id":"snt_ch_work_ddk_8_3","chapterId":"ch_work_ddk_8","textTraditional":"夫唯不爭，故無尤。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"phù duy bất tranh， cố vô vưu。","pinyinReading":"fú wéi bù zhēng， gù wú yóu。","translation":"Chính vì không tranh giành, nên không có lỗi lầm."},

  {"id":"snt_ch_work_ddk_9_1","chapterId":"ch_work_ddk_9","textTraditional":"持而盈之，不如其已；揣而銳之，不可長保。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"trì nhi doanh chi， bất như kỳ dĩ； sủy nhi duệ chi， bất khả trường bảo。","pinyinReading":"chí ér yíng zhī， bù rú qí yǐ； chuǎi ér ruì zhī， bù kě cháng bǎo。","translation":"Giữ mà đổ đầy, chẳng bằng thôi đi; mài cho sắc bén, không thể giữ lâu.","textSimplified":"持而盈之，不如其已；揣而锐之，不可长保。"},
  {"id":"snt_ch_work_ddk_9_2","chapterId":"ch_work_ddk_9","textTraditional":"金玉滿堂，莫之能守；富貴而驕，自遺其咎。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"kim ngọc mãn đường， mạc chi năng thủ； phú quý nhi kiêu， tự di kỳ cữu。","pinyinReading":"jīn yù mǎn táng， mò zhī néng shǒu； fù guì ér jiāo， zì yí qí jiù。","translation":"Vàng ngọc đầy nhà, không ai giữ nổi; giàu sang mà kiêu căng, tự chuốc lấy họa.","textSimplified":"金玉满堂，莫之能守；富贵而骄，自遗其咎。"},
  {"id":"snt_ch_work_ddk_9_3","chapterId":"ch_work_ddk_9","textTraditional":"功遂身退，天之道也。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"công toại thân thoái， thiên chi đạo dã。","pinyinReading":"gōng suì shēn tuì， tiān zhī dào yě。","translation":"Công thành thân lui, đó là đạo trời."},

  {"id":"snt_ch_work_ddk_10_1","chapterId":"ch_work_ddk_10","textTraditional":"載營魄抱一，能無離乎？專氣致柔，能如嬰兒乎？","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"tái doanh phách bão nhất， năng vô ly hồ？ chuyên khí trí nhu， năng như anh nhi hồ？","pinyinReading":"zài yíng pò bào yī， néng wú lí hū？ zhuān qì zhì róu， néng rú yīng ér hū？","translation":"Giữ hồn phách ôm lấy Một, có thể không lìa được chăng? Chuyên chú khí để đạt sự mềm mại, có thể như trẻ sơ sinh chăng?","textSimplified":"载营魄抱一，能无离乎？专气致柔，能如婴儿乎？"},
  {"id":"snt_ch_work_ddk_10_2","chapterId":"ch_work_ddk_10","textTraditional":"滌除玄覽，能無疵乎？愛民治國，能無為乎？","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"địch trừ huyền lãm， năng vô tì hồ？ ái dân trị quốc， năng vô vi hồ？","pinyinReading":"dí chú xuán lǎn， néng wú cī hū？ ài mín zhì guó， néng wú wéi hū？","translation":"Gột rửa cái nhìn sâu xa, có thể không tì vết chăng? Yêu dân trị nước, có thể vô vi chăng?","textSimplified":"涤除玄览，能无疵乎？爱民治国，能无为乎？"},
  {"id":"snt_ch_work_ddk_10_3","chapterId":"ch_work_ddk_10","textTraditional":"天門開闔，能為雌乎？明白四達，能無知乎？","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"thiên môn khai hạp， năng vi thư hồ？ minh bạch tứ đạt， năng vô tri hồ？","pinyinReading":"tiān mén kāi hé， néng wéi cí hū？ míng bái sì dá， néng wú zhī hū？","translation":"Cửa trời đóng mở, có thể giữ tĩnh lặng chăng? Sáng suốt thấu hiểu bốn phương, có thể không dùng trí chăng?","textSimplified":"天门开阖，能为雌乎？明白四达，能无知乎？"},
  {"id":"snt_ch_work_ddk_10_4","chapterId":"ch_work_ddk_10","textTraditional":"生之畜之，生而不有，為而不恃，長而不宰，是謂玄德。","sentenceOrder":4,"paragraphGroup":2,"hanVietReading":"sinh chi húc chi， sinh nhi bất hữu， vi nhi bất thị， trưởng nhi bất tể， thị vị huyền đức。","pinyinReading":"shēng zhī xù zhī， shēng ér bù yǒu， wéi ér bù shì， zhǎng ér bù zǎi， shì wèi xuán dé。","translation":"Sinh ra và nuôi nấng, sinh mà không chiếm hữu, làm mà không cậy nhờ, nuôi lớn mà không cai quản — đó gọi là Huyền Đức.","textSimplified":"生之畜之，生而不有，为而不恃，长而不宰，是谓玄德。"},

  {"id":"snt_ch_work_ddk_11_1","chapterId":"ch_work_ddk_11","textTraditional":"三十輻共一轂，當其無，有車之用。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"tam thập bức cộng nhất cốc， đương kỳ vô， hữu xa chi dụng。","pinyinReading":"sān shí fú gòng yī gǔ， dāng qí wú， yǒu chē zhī yòng。","translation":"Ba mươi nan hoa cùng chung một bầu xe, nhờ chỗ trống mà xe mới dùng được.","textSimplified":"三十辐共一毂，当其无，有车之用。"},
  {"id":"snt_ch_work_ddk_11_2","chapterId":"ch_work_ddk_11","textTraditional":"埏埴以為器，當其無，有器之用。鑿戶牖以為室，當其無，有室之用。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"thiên thực dĩ vi khí， đương kỳ vô， hữu khí chi dụng。 tạc hộ dũ dĩ vi thất， đương kỳ vô， hữu thất chi dụng。","pinyinReading":"shān zhí yǐ wéi qì， dāng qí wú， yǒu qì zhī yòng。 záo hù yǒu yǐ wéi shì， dāng qí wú， yǒu shì zhī yòng。","translation":"Nhào đất để làm đồ gốm, nhờ chỗ trống mà đồ gốm mới dùng được. Khoét cửa để làm phòng, nhờ chỗ trống mà phòng mới dùng được.","textSimplified":"埏埴以为器，当其无，有器之用。凿户牖以为室，当其无，有室之用。"},
  {"id":"snt_ch_work_ddk_11_3","chapterId":"ch_work_ddk_11","textTraditional":"故有之以為利，無之以為用。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"cố hữu chi dĩ vi lợi， vô chi dĩ vi dụng。","pinyinReading":"gù yǒu zhī yǐ wéi lì， wú zhī yǐ wéi yòng。","translation":"Cho nên \"có\" đem lại cái lợi, \"không\" đem lại công dụng.","textSimplified":"故有之以为利，无之以为用。"},

  {"id":"snt_ch_work_ddk_12_1","chapterId":"ch_work_ddk_12","textTraditional":"五色令人目盲；五音令人耳聾；五味令人口爽。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"ngũ sắc lệnh nhân mục manh； ngũ âm lệnh nhân nhĩ lung； ngũ vị lệnh nhân khẩu sảng。","pinyinReading":"wǔ sè lìng rén mù máng； wǔ yīn lìng rén ěr lóng； wǔ wèi lìng rén kǒu shuǎng。","translation":"Năm màu làm mắt người mù lòa; năm âm làm tai người điếc đặc; năm vị làm miệng người tê liệt.","textSimplified":"五色令人目盲；五音令人耳聋；五味令人口爽。"},
  {"id":"snt_ch_work_ddk_12_2","chapterId":"ch_work_ddk_12","textTraditional":"馳騁畋獵，令人心發狂；難得之貨，令人行妨。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"trì sính điền liệp， lệnh nhân tâm phát cuồng； nan đắc chi hóa， lệnh nhân hành phương。","pinyinReading":"chí chěng tián liè， lìng rén xīn fā kuáng； nán dé zhī huò， lìng rén xíng fáng。","translation":"Phi ngựa đi săn, khiến lòng người phát cuồng; của cải khó được, khiến hành vi người ta bị trở ngại.","textSimplified":"驰骋畋猎，令人心发狂；难得之货，令人行妨。"},
  {"id":"snt_ch_work_ddk_12_3","chapterId":"ch_work_ddk_12","textTraditional":"是以聖人為腹不為目，故去彼取此。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"thị dĩ thánh nhân vi phúc bất vi mục， cố khứ bỉ thủ thử。","pinyinReading":"shì yǐ shèng rén wéi fù bù wéi mù， gù qù bǐ qǔ cǐ。","translation":"Vì thế thánh nhân lo cho bụng chứ không lo cho mắt, nên bỏ cái kia mà lấy cái này.","textSimplified":"是以圣人为腹不为目，故去彼取此。"},

  {"id":"snt_ch_work_ddk_13_1","chapterId":"ch_work_ddk_13","textTraditional":"寵辱若驚，貴大患若身。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"sủng nhục nhược kinh， quý đại hoạn nhược thân。","pinyinReading":"chǒng rǔ ruò jīng， guì dà huàn ruò shēn。","translation":"Được sủng hay bị nhục đều hoảng sợ, quý trọng đại họa như quý trọng thân mình.","textSimplified":"宠辱若惊，贵大患若身。"},
  {"id":"snt_ch_work_ddk_13_2","chapterId":"ch_work_ddk_13","textTraditional":"何謂寵辱若驚？寵為下，得之若驚，失之若驚，是謂寵辱若驚。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"hà vị sủng nhục nhược kinh？ sủng vi hạ， đắc chi nhược kinh， thất chi nhược kinh， thị vị sủng nhục nhược kinh。","pinyinReading":"hé wèi chǒng rǔ ruò jīng？ chǒng wéi xià， dé zhī ruò jīng， shī zhī ruò jīng， shì wèi chǒng rǔ ruò jīng。","translation":"Sao gọi là được sủng nhục đều hoảng sợ? Sủng là thấp kém, được thì hoảng sợ, mất thì hoảng sợ, đó gọi là sủng nhục đều hoảng sợ.","textSimplified":"何谓宠辱若惊？宠为下，得之若惊，失之若惊，是谓宠辱若惊。"},
  {"id":"snt_ch_work_ddk_13_3","chapterId":"ch_work_ddk_13","textTraditional":"何謂貴大患若身？吾所以有大患者，為吾有身，及吾無身，吾有何患？","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"hà vị quý đại hoạn nhược thân？ ngô sở dĩ hữu đại hoạn giả， vị ngô hữu thân， cập ngô vô thân， ngô hữu hà hoạn？","pinyinReading":"hé wèi guì dà huàn ruò shēn？ wú suǒ yǐ yǒu dà huàn zhě， wèi wú yǒu shēn， jí wú wú shēn， wú yǒu hé huàn？","translation":"Sao gọi là quý đại họa như thân? Ta sở dĩ có đại họa là vì ta có thân, nếu ta không có thân thì ta có họa gì?","textSimplified":"何谓贵大患若身？吾所以有大患者，为吾有身，及吾无身，吾有何患？"},
  {"id":"snt_ch_work_ddk_13_4","chapterId":"ch_work_ddk_13","textTraditional":"故貴以身為天下，若可寄天下；愛以身為天下，若可託天下。","sentenceOrder":4,"paragraphGroup":2,"hanVietReading":"cố quý dĩ thân vi thiên hạ， nhược khả ký thiên hạ； ái dĩ thân vi thiên hạ， nhược khả thác thiên hạ。","pinyinReading":"gù guì yǐ shēn wéi tiān xià， ruò kě jì tiān xià； ài yǐ shēn wéi tiān xià， ruò kě tuō tiān xià。","translation":"Cho nên người quý thân mình vì thiên hạ, mới có thể giao phó thiên hạ; người yêu thân mình vì thiên hạ, mới có thể gửi gắm thiên hạ.","textSimplified":"故贵以身为天下，若可寄天下；爱以身为天下，若可托天下。"},

  {"id":"snt_ch_work_ddk_14_1","chapterId":"ch_work_ddk_14","textTraditional":"視之不見名曰夷，聽之不聞名曰希，搏之不得名曰微。此三者不可致詰，故混而為一。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thị chi bất kiến danh viết di， thính chi bất văn danh viết hi， bác chi bất đắc danh viết vi。 thử tam giả bất khả trí cật， cố hỗn nhi vi nhất。","pinyinReading":"shì zhī bù jiàn míng yuē yí， tīng zhī bù wén míng yuē xī， bó zhī bù dé míng yuē wēi。 cǐ sān zhě bù kě zhì jié， gù hùn ér wéi yī。","translation":"Nhìn mà không thấy gọi là Di; nghe mà không nghe gọi là Hi; nắm mà không được gọi là Vi. Ba điều này không thể truy cứu, nên trộn lẫn thành một.","textSimplified":"视之不见名曰夷，听之不闻名曰希，搏之不得名曰微。此三者不可致诘，故混而为一。"},
  {"id":"snt_ch_work_ddk_14_2","chapterId":"ch_work_ddk_14","textTraditional":"其上不皦，其下不昧。繩繩兮不可名，復歸於無物。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"kỳ thượng bất kiểu， kỳ hạ bất muội。 thằng thằng hề bất khả danh， phục quy ư vô vật。","pinyinReading":"qí shàng bù jiǎo， qí xià bù mèi。 shéng shéng xī bù kě míng， fù guī yú wú wù。","translation":"Phía trên không sáng, phía dưới không tối. Miên man không thể đặt tên, trở về cõi không có vật.","textSimplified":"其上不皦，其下不昧。绳绳兮不可名，复归于无物。"},
  {"id":"snt_ch_work_ddk_14_3","chapterId":"ch_work_ddk_14","textTraditional":"是謂無狀之狀，無物之象，是謂惚恍。迎之不見其首，隨之不見其後。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"thị vị vô trạng chi trạng， vô vật chi tượng， thị vị hốt hoảng。 nghênh chi bất kiến kỳ thủ， tùy chi bất kiến kỳ hậu。","pinyinReading":"shì wèi wú zhuàng zhī zhuàng， wú wù zhī xiàng， shì wèi hū huǎng。 yíng zhī bù jiàn qí shǒu， suí zhī bù jiàn qí hòu。","translation":"Đó gọi là hình không hình, tượng không vật, gọi là hoảng hốt. Đón phía trước không thấy đầu, theo phía sau không thấy đuôi.","textSimplified":"是谓无状之状，无物之象，是谓惚恍。迎之不见其首，随之不见其后。"},
  {"id":"snt_ch_work_ddk_14_4","chapterId":"ch_work_ddk_14","textTraditional":"執古之道，以御今之有。能知古始，是謂道紀。","sentenceOrder":4,"paragraphGroup":2,"hanVietReading":"chấp cổ chi đạo， dĩ ngự kim chi hữu。 năng tri cổ thủy， thị vị đạo kỷ。","pinyinReading":"zhí gǔ zhī dào， yǐ yù jīn zhī yǒu。 néng zhī gǔ shǐ， shì wèi dào jì。","translation":"Nắm giữ Đạo xưa để điều khiển sự vật ngày nay. Biết được khởi đầu thuở xưa, đó gọi là mối giềng của Đạo.","textSimplified":"执古之道，以御今之有。能知古始，是谓道纪。"},

  {"id":"snt_ch_work_ddk_15_1","chapterId":"ch_work_ddk_15","textTraditional":"古之善為士者，微妙玄通，深不可識。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"cổ chi thiện vi sĩ giả， vi diệu huyền thông， thâm bất khả thức。","pinyinReading":"gǔ zhī shàn wéi shì zhě， wēi miào xuán tōng， shēn bù kě shí。","translation":"Bậc sĩ giỏi thời xưa, tinh vi huyền diệu thông suốt, sâu xa không thể biết hết.","textSimplified":"古之善为士者，微妙玄通，深不可识。"},
  {"id":"snt_ch_work_ddk_15_2","chapterId":"ch_work_ddk_15","textTraditional":"夫唯不可識，故強為之容：豫兮若冬涉川，猶兮若畏四鄰，儼兮其若客，渙兮若冰之將釋，敦兮其若樸，曠兮其若谷，混兮其若濁。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"phù duy bất khả thức， cố cưỡng vi chi dung： dự hề nhược đông thiệp xuyên， do hề nhược úy tứ lân， nghiễm hề kỳ nhược khách， hoán hề nhược băng chi tương thích， đôn hề kỳ nhược phác， khoáng hề kỳ nhược cốc， hỗn hề kỳ nhược trọc。","pinyinReading":"fú wéi bù kě shí， gù qiǎng wéi zhī róng： yù xī ruò dōng shè chuān， yóu xī ruò wèi sì lín， yǎn xī qí ruò kè， huàn xī ruò bīng zhī jiāng shì， dūn xī qí ruò pǔ， kuàng xī qí ruò gǔ， hùn xī qí ruò zhuó。","translation":"Vì không thể nhận biết, nên gượng mô tả: thận trọng như mùa đông lội qua sông, dè dặt như sợ bốn bề láng giềng, trang nghiêm như làm khách, tan chảy như băng sắp tan, mộc mạc như gỗ chưa đẽo, rộng mở như hang trống, hòa trộn như nước đục.","textSimplified":"夫唯不可识，故强为之容：豫兮若冬涉川，犹兮若畏四邻，俨兮其若客，涣兮若冰之将释，敦兮其若朴，旷兮其若谷，混兮其若浊。"},
  {"id":"snt_ch_work_ddk_15_3","chapterId":"ch_work_ddk_15","textTraditional":"孰能濁以靜之徐清？孰能安以動之徐生？","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"thục năng trọc dĩ tĩnh chi từ thanh？ thục năng an dĩ động chi từ sinh？","pinyinReading":"shú néng zhuó yǐ jìng zhī xú qīng？ shú néng ān yǐ dòng zhī xú shēng？","translation":"Ai có thể để đục lắng yên cho từ từ trong? Ai có thể để yên ổn rồi chuyển động cho từ từ sinh?","textSimplified":"孰能浊以静之徐清？孰能安以动之徐生？"},
  {"id":"snt_ch_work_ddk_15_4","chapterId":"ch_work_ddk_15","textTraditional":"保此道者不欲盈。夫唯不盈，故能蔽而新成。","sentenceOrder":4,"paragraphGroup":2,"hanVietReading":"bảo thử đạo giả bất dục doanh。 phù duy bất doanh， cố năng tệ nhi tân thành。","pinyinReading":"bǎo cǐ dào zhě bù yù yíng。 fú wéi bù yíng， gù néng bì ér xīn chéng。","translation":"Người giữ Đạo này không muốn đầy. Chính vì không đầy, nên mới có thể cũ mà thành mới.","textSimplified":"保此道者不欲盈。夫唯不盈，故能蔽而新成。"},

  {"id":"snt_ch_work_ddk_16_1","chapterId":"ch_work_ddk_16","textTraditional":"致虛極，守靜篤。萬物並作，吾以觀復。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"trí hư cực， thủ tĩnh đốc。 vạn vật tịnh tác， ngô dĩ quan phục。","pinyinReading":"zhì xū jí， shǒu jìng dǔ。 wàn wù bìng zuò， wú yǐ guān fù。","translation":"Đạt tới hư không cùng cực, giữ tĩnh lặng vững chắc. Muôn vật cùng sinh sôi, ta nhìn chúng quay về.","textSimplified":"致虚极，守静笃。万物并作，吾以观复。"},
  {"id":"snt_ch_work_ddk_16_2","chapterId":"ch_work_ddk_16","textTraditional":"夫物芸芸，各復歸其根。歸根曰靜，靜曰復命。復命曰常，知常曰明。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"phù vật vân vân， các phục quy kỳ căn。 quy căn viết tĩnh， tĩnh viết phục mệnh。 phục mệnh viết thường， tri thường viết minh。","pinyinReading":"fú wù yún yún， gè fù guī qí gēn。 guī gēn yuē jìng， jìng yuē fù mìng。 fù mìng yuē cháng， zhī cháng yuē míng。","translation":"Muôn vật phồn thịnh, rồi đều quay về gốc rễ. Về gốc gọi là tĩnh, tĩnh gọi là phục mệnh. Phục mệnh gọi là thường, biết thường gọi là sáng suốt.","textSimplified":"夫物芸芸，各复归其根。归根曰静，静曰复命。复命曰常，知常曰明。"},
  {"id":"snt_ch_work_ddk_16_3","chapterId":"ch_work_ddk_16","textTraditional":"不知常，妄作凶。知常容，容乃公，公乃全，全乃天，天乃道，道乃久，沒身不殆。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"bất tri thường， vọng tác hung。 tri thường dung， dung nãi công， công nãi toàn， toàn nãi thiên， thiên nãi đạo， đạo nãi cửu， một thân bất đãi。","pinyinReading":"bù zhī cháng， wàng zuò xiōng。 zhī cháng róng， róng nǎi gōng， gōng nǎi quán， quán nǎi tiān， tiān nǎi dào， dào nǎi jiǔ， mò shēn bù dài。","translation":"Không biết lẽ thường thì vọng động gây họa. Biết thường thì bao dung, bao dung thì công bằng, công bằng thì toàn vẹn, toàn vẹn thì hợp trời, hợp trời thì hợp Đạo, hợp Đạo thì trường cửu, suốt đời không nguy.","textSimplified":"不知常，妄作凶。知常容，容乃公，公乃全，全乃天，天乃道，道乃久，没身不殆。"},

  {"id":"snt_ch_work_ddk_17_1","chapterId":"ch_work_ddk_17","textTraditional":"太上，不知有之；其次，親而譽之；其次，畏之；其次，侮之。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thái thượng， bất tri hữu chi； kỳ thứ， thân nhi dự chi； kỳ thứ， úy chi； kỳ thứ， vũ chi。","pinyinReading":"tài shàng， bù zhī yǒu zhī； qí cì， qīn ér yù zhī； qí cì， wèi zhī； qí cì， wǔ zhī。","translation":"Bậc cao nhất, dân không biết có; bậc kế, dân thân gần và ca tụng; bậc kế nữa, dân sợ hãi; bậc thấp nhất, dân khinh thường.","textSimplified":"太上，不知有之；其次，亲而誉之；其次，畏之；其次，侮之。"},
  {"id":"snt_ch_work_ddk_17_2","chapterId":"ch_work_ddk_17","textTraditional":"信不足焉，有不信焉。悠兮其貴言。功成事遂，百姓皆謂我自然。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"tín bất túc yên， hữu bất tín yên。 du hề kỳ quý ngôn。 công thành sự toại， bách tính giai vị ngã tự nhiên。","pinyinReading":"xìn bù zú yān， yǒu bù xìn yān。 yōu xī qí guì yán。 gōng chéng shì suì， bǎi xìng jiē wèi wǒ zì rán。","translation":"Lòng tin không đủ thì có sự bất tín. Ung dung thay, quý lời nói ít. Công thành sự tựu, trăm họ đều nói: ta tự nhiên mà thế.","textSimplified":"信不足焉，有不信焉。悠兮其贵言。功成事遂，百姓皆谓我自然。"},

  {"id":"snt_ch_work_ddk_18_1","chapterId":"ch_work_ddk_18","textTraditional":"大道廢，有仁義；智慧出，有大偽。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"đại đạo phế， hữu nhân nghĩa； trí tuệ xuất， hữu đại ngụy。","pinyinReading":"dà dào fèi， yǒu rén yì； zhì huì chū， yǒu dà wěi。","translation":"Đại Đạo bị phế bỏ mới có nhân nghĩa; trí tuệ xuất hiện mới có giả dối lớn.","textSimplified":"大道废，有仁义；智慧出，有大伪。"},
  {"id":"snt_ch_work_ddk_18_2","chapterId":"ch_work_ddk_18","textTraditional":"六親不和，有孝慈；國家昏亂，有忠臣。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"lục thân bất hòa， hữu hiếu từ； quốc gia hôn loạn， hữu trung thần。","pinyinReading":"liù qīn bù hé， yǒu xiào cí； guó jiā hūn luàn， yǒu zhōng chén。","translation":"Sáu thân không hòa thuận mới có hiếu từ; nước nhà hôn loạn mới có trung thần.","textSimplified":"六亲不和，有孝慈；国家昏乱，有忠臣。"},

  {"id":"snt_ch_work_ddk_19_1","chapterId":"ch_work_ddk_19","textTraditional":"絕聖棄智，民利百倍；絕仁棄義，民復孝慈；絕巧棄利，盜賊無有。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"tuyệt thánh khí trí， dân lợi bách bội； tuyệt nhân khí nghĩa， dân phục hiếu từ； tuyệt xảo khí lợi， đạo tặc vô hữu。","pinyinReading":"jué shèng qì zhì， mín lì bǎi bèi； jué rén qì yì， mín fù xiào cí； jué qiǎo qì lì， dào zéi wú yǒu。","translation":"Dứt bỏ thánh trí, dân lợi gấp trăm; dứt bỏ nhân nghĩa, dân trở lại hiếu từ; dứt bỏ khéo léo bỏ lợi, trộm cướp không còn.","textSimplified":"绝圣弃智，民利百倍；绝仁弃义，民复孝慈；绝巧弃利，盗贼无有。"},
  {"id":"snt_ch_work_ddk_19_2","chapterId":"ch_work_ddk_19","textTraditional":"此三者以為文不足，故令有所屬：見素抱樸，少私寡欲，絕學無憂。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thử tam giả dĩ vi văn bất túc， cố lệnh hữu sở thuộc： kiến tố bão phác， thiểu tư quả dục， tuyệt học vô ưu。","pinyinReading":"cǐ sān zhě yǐ wéi wén bù zú， gù lìng yǒu suǒ shǔ： xiàn sù bào pǔ， shǎo sī guǎ yù， jué xué wú yōu。","translation":"Ba điều này làm văn vẻ không đủ, nên khiến có chỗ nương theo: giữ mộc mạc ôm chất phác, ít riêng tư bớt ham muốn, dứt học vấn thì hết lo.","textSimplified":"此三者以为文不足，故令有所属：见素抱朴，少私寡欲，绝学无忧。"},

  {"id":"snt_ch_work_ddk_20_1","chapterId":"ch_work_ddk_20","textTraditional":"唯之與阿，相去幾何？美之與惡，相去若何？人之所畏，不可不畏。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"duy chi dữ a， tương khứ kỷ hà？ mỹ chi dữ ác， tương khứ nhược hà？ nhân chi sở úy， bất khả bất úy。","pinyinReading":"wéi zhī yǔ ē， xiāng qù jǐ hé？ měi zhī yǔ è， xiāng qù ruò hé？ rén zhī suǒ wèi， bù kě bù wèi。","translation":"Dạ vâng và quát nạt, cách nhau bao xa? Đẹp và xấu, cách nhau bao nhiêu? Điều người ta sợ, ta không thể không sợ.","textSimplified":"唯之与阿，相去几何？美之与恶，相去若何？人之所畏，不可不畏。"},
  {"id":"snt_ch_work_ddk_20_2","chapterId":"ch_work_ddk_20","textTraditional":"荒兮其未央哉！衆人熙熙，如享太牢，如春登臺。我獨泊兮其未兆，沌沌兮如嬰兒之未孩。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"hoang hề kỳ vị ương tai！ chúng nhân hi hi， như hưởng thái lao， như xuân đăng đài。 ngã độc bạc hề kỳ vị triệu， độn độn hề như anh nhi chi vị hài。","pinyinReading":"huāng xī qí wèi yāng zāi！ zhòng rén xī xī， rú xiǎng tài láo， rú chūn dēng tái。 wǒ dú bó xī qí wèi zhào， dùn dùn xī rú yīng ér zhī wèi hái。","translation":"Mênh mông thay, chưa có bờ bến! Mọi người hớn hở như dự tiệc lớn, như mùa xuân lên đài. Riêng ta lặng lẽ chưa lộ dấu hiệu, hồn nhiên như trẻ sơ sinh chưa biết cười.","textSimplified":"荒兮其未央哉！众人熙熙，如享太牢，如春登台。我独泊兮其未兆，沌沌兮如婴儿之未孩。"},
  {"id":"snt_ch_work_ddk_20_3","chapterId":"ch_work_ddk_20","textTraditional":"儽儽兮若無所歸。衆人皆有餘，而我獨若遺。我愚人之心也哉！","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"luy luy hề nhược vô sở quy。 chúng nhân giai hữu dư， nhi ngã độc nhược di。 ngã ngu nhân chi tâm dã tai！","pinyinReading":"lěi lěi xī ruò wú suǒ guī。 zhòng rén jiē yǒu yú， ér wǒ dú ruò yí。 wǒ yú rén zhī xīn yě zāi！","translation":"Bơ vơ như không nơi nương tựa. Mọi người đều có thừa, riêng ta như thiếu thốn. Ta có tấm lòng ngu muội thay!","textSimplified":"儽儽兮若无所归。众人皆有余，而我独若遗。我愚人之心也哉！"},
  {"id":"snt_ch_work_ddk_20_4","chapterId":"ch_work_ddk_20","textTraditional":"俗人昭昭，我獨昏昏。俗人察察，我獨悶悶。澹兮其若海，飂兮若無止。","sentenceOrder":4,"paragraphGroup":2,"hanVietReading":"tục nhân chiêu chiêu， ngã độc hôn hôn。 tục nhân sát sát， ngã độc muộn muộn。 đạm hề kỳ nhược hải， liêu hề nhược vô chỉ。","pinyinReading":"sú rén zhāo zhāo， wǒ dú hūn hūn。 sú rén chá chá， wǒ dú mèn mèn。 dàn xī qí ruò hǎi， liáo xī ruò wú zhǐ。","translation":"Người đời sáng rỡ, riêng ta tối mờ. Người đời tinh tường, riêng ta u mê. Lặng lẽ như biển cả, phiêu diêu như không dừng.","textSimplified":"俗人昭昭，我独昏昏。俗人察察，我独闷闷。澹兮其若海，飂兮若无止。"},
  {"id":"snt_ch_work_ddk_20_5","chapterId":"ch_work_ddk_20","textTraditional":"衆人皆有以，而我獨頑且鄙。我獨異於人，而貴食母。","sentenceOrder":5,"paragraphGroup":3,"hanVietReading":"chúng nhân giai hữu dĩ， nhi ngã độc ngoan thả bỉ。 ngã độc dị ư nhân， nhi quý thực mẫu。","pinyinReading":"zhòng rén jiē yǒu yǐ， ér wǒ dú wán qiě bǐ。 wǒ dú yì yú rén， ér guì shí mǔ。","translation":"Mọi người đều có sở dụng, riêng ta ngoan ngu và quê mùa. Ta khác hẳn mọi người, quý trọng nguồn nuôi dưỡng (Đạo).","textSimplified":"众人皆有以，而我独顽且鄙。我独异于人，而贵食母。"},

  {"id":"snt_ch_work_ddk_21_1","chapterId":"ch_work_ddk_21","textTraditional":"孔德之容，惟道是從。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"khổng đức chi dung， duy đạo thị tòng。","pinyinReading":"kǒng dé zhī róng， wéi dào shì cóng。","translation":"Cái dáng vẻ của đức lớn, chỉ theo Đạo mà thôi."},
  {"id":"snt_ch_work_ddk_21_2","chapterId":"ch_work_ddk_21","textTraditional":"道之為物，惟恍惟惚。惚兮恍兮，其中有象；恍兮惚兮，其中有物。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"đạo chi vi vật， duy hoảng duy hốt。 hốt hề hoảng hề， kỳ trung hữu tượng； hoảng hề hốt hề， kỳ trung hữu vật。","pinyinReading":"dào zhī wéi wù， wéi huǎng wéi hū。 hū xī huǎng xī， qí zhōng yǒu xiàng； huǎng xī hū xī， qí zhōng yǒu wù。","translation":"Đạo là vật, chỉ hoảng chỉ hốt. Hốt rồi hoảng, trong đó có hình tượng; hoảng rồi hốt, trong đó có vật.","textSimplified":"道之为物，惟恍惟惚。惚兮恍兮，其中有象；恍兮惚兮，其中有物。"},
  {"id":"snt_ch_work_ddk_21_3","chapterId":"ch_work_ddk_21","textTraditional":"窈兮冥兮，其中有精；其精甚真，其中有信。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"yểu hề minh hề， kỳ trung hữu tinh； kỳ tinh thậm chân， kỳ trung hữu tín。","pinyinReading":"yǎo xī míng xī， qí zhōng yǒu jīng； qí jīng shèn zhēn， qí zhōng yǒu xìn。","translation":"Sâu thẳm tối mờ, trong đó có tinh chất; tinh chất ấy rất chân thật, trong đó có sự xác tín."},
  {"id":"snt_ch_work_ddk_21_4","chapterId":"ch_work_ddk_21","textTraditional":"自今及古，其名不去，以閱衆甫。吾何以知衆甫之狀哉？以此。","sentenceOrder":4,"paragraphGroup":2,"hanVietReading":"tự kim cập cổ， kỳ danh bất khứ， dĩ duyệt chúng phủ。 ngô hà dĩ tri chúng phủ chi trạng tai？ dĩ thử。","pinyinReading":"zì jīn jí gǔ， qí míng bù qù， yǐ yuè zhòng fǔ。 wú hé yǐ zhī zhòng fǔ zhī zhuàng zāi？ yǐ cǐ。","translation":"Từ nay đến xưa, tên nó không mất, dùng để xem xét muôn vật khởi đầu. Ta làm sao biết hình trạng của muôn vật khởi đầu? Nhờ vào đây.","textSimplified":"自今及古，其名不去，以阅众甫。吾何以知众甫之状哉？以此。"},

  {"id":"snt_ch_work_ddk_22_1","chapterId":"ch_work_ddk_22","textTraditional":"曲則全，枉則直，窪則盈，弊則新，少則得，多則惑。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"khúc tắc toàn， uổng tắc trực， oa tắc doanh， tệ tắc tân， thiểu tắc đắc， đa tắc hoặc。","pinyinReading":"qū zé quán， wǎng zé zhí， wā zé yíng， bì zé xīn， shǎo zé dé， duō zé huò。","translation":"Cong thì được vẹn toàn, uốn thì được thẳng, trũng thì được đầy, cũ thì được mới, ít thì được nhiều, nhiều thì mê hoặc.","textSimplified":"曲则全，枉则直，洼则盈，弊则新，少则得，多则惑。"},
  {"id":"snt_ch_work_ddk_22_2","chapterId":"ch_work_ddk_22","textTraditional":"是以聖人抱一為天下式。不自見故明，不自是故彰，不自伐故有功，不自矜故長。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thị dĩ thánh nhân bão nhất vi thiên hạ thức。 bất tự kiến cố minh， bất tự thị cố chương， bất tự phạt cố hữu công， bất tự căng cố trường。","pinyinReading":"shì yǐ shèng rén bào yī wéi tiān xià shì。 bù zì xiàn gù míng， bù zì shì gù zhāng， bù zì fá gù yǒu gōng， bù zì jīn gù cháng。","translation":"Vì thế thánh nhân ôm giữ cái Một làm khuôn phép cho thiên hạ. Không tự phô nên sáng, không tự cho là đúng nên rõ ràng, không tự khoe nên có công, không tự kiêu nên trường tồn.","textSimplified":"是以圣人抱一为天下式。不自见故明，不自是故彰，不自伐故有功，不自矜故长。"},
  {"id":"snt_ch_work_ddk_22_3","chapterId":"ch_work_ddk_22","textTraditional":"夫唯不爭，故天下莫能與之爭。古之所謂曲則全者，豈虛言哉！誠全而歸之。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"phù duy bất tranh， cố thiên hạ mạc năng dữ chi tranh。 cổ chi sở vị khúc tắc toàn giả， khởi hư ngôn tai！ thành toàn nhi quy chi。","pinyinReading":"fú wéi bù zhēng， gù tiān xià mò néng yǔ zhī zhēng。 gǔ zhī suǒ wèi qū zé quán zhě， qǐ xū yán zāi！ chéng quán ér guī zhī。","translation":"Chính vì không tranh, nên thiên hạ không ai tranh nổi. Lời xưa nói \"cong thì vẹn toàn\", há phải lời nói suông! Thật sự vẹn toàn mà trở về.","textSimplified":"夫唯不争，故天下莫能与之争。古之所谓曲则全者，岂虚言哉！诚全而归之。"},

  {"id":"snt_ch_work_ddk_23_1","chapterId":"ch_work_ddk_23","textTraditional":"希言自然。故飄風不終朝，驟雨不終日。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"hi ngôn tự nhiên。 cố phiêu phong bất chung triêu， sậu vũ bất chung nhật。","pinyinReading":"xī yán zì rán。 gù piāo fēng bù zhōng zhāo， zhòu yǔ bù zhōng rì。","translation":"Ít nói là tự nhiên. Gió lốc không thổi suốt buổi sáng, mưa rào không mưa suốt ngày.","textSimplified":"希言自然。故飘风不终朝，骤雨不终日。"},
  {"id":"snt_ch_work_ddk_23_2","chapterId":"ch_work_ddk_23","textTraditional":"孰為此者？天地。天地尚不能久，而況於人乎？","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"thục vi thử giả？ thiên địa。 thiên địa thượng bất năng cửu， nhi huống ư nhân hồ？","pinyinReading":"shú wéi cǐ zhě？ tiān dì。 tiān dì shàng bù néng jiǔ， ér kuàng yú rén hū？","translation":"Ai làm ra chúng? Trời đất. Trời đất còn không thể lâu dài, huống chi con người?"},
  {"id":"snt_ch_work_ddk_23_3","chapterId":"ch_work_ddk_23","textTraditional":"故從事於道者，同於道；德者，同於德；失者，同於失。同於道者，道亦樂得之；同於德者，德亦樂得之；同於失者，失亦樂得之。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"cố tòng sự ư đạo giả， đồng ư đạo； đức giả， đồng ư đức； thất giả， đồng ư thất。 đồng ư đạo giả， đạo diệc lạc đắc chi； đồng ư đức giả， đức diệc lạc đắc chi； đồng ư thất giả， thất diệc lạc đắc chi。","pinyinReading":"gù cóng shì yú dào zhě， tóng yú dào； dé zhě， tóng yú dé； shī zhě， tóng yú shī。 tóng yú dào zhě， dào yì lè dé zhī； tóng yú dé zhě， dé yì lè dé zhī； tóng yú shī zhě， shī yì lè dé zhī。","translation":"Cho nên người theo Đạo thì đồng với Đạo; theo Đức thì đồng với Đức; theo sự mất mát thì đồng với mất mát. Hợp với Đạo thì Đạo cũng vui được người ấy; hợp với Đức thì Đức cũng vui được người ấy; hợp với mất mát thì mất mát cũng vui được người ấy.","textSimplified":"故从事于道者，同于道；德者，同于德；失者，同于失。同于道者，道亦乐得之；同于德者，德亦乐得之；同于失者，失亦乐得之。"},

  {"id":"snt_ch_work_ddk_24_1","chapterId":"ch_work_ddk_24","textTraditional":"企者不立，跨者不行。自見者不明，自是者不彰，自伐者無功，自矜者不長。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"xí giả bất lập， khóa giả bất hành。 tự kiến giả bất minh， tự thị giả bất chương， tự phạt giả vô công， tự căng giả bất trường。","pinyinReading":"qì zhě bù lì， kuà zhě bù xíng。 zì xiàn zhě bù míng， zì shì zhě bù zhāng， zì fá zhě wú gōng， zì jīn zhě bù cháng。","translation":"Kiễng chân thì không đứng vững, bước rộng thì không đi xa. Tự phô thì không sáng, tự cho đúng thì không rõ, tự khoe thì không có công, tự kiêu thì không trường tồn.","textSimplified":"企者不立，跨者不行。自见者不明，自是者不彰，自伐者无功，自矜者不长。"},
  {"id":"snt_ch_work_ddk_24_2","chapterId":"ch_work_ddk_24","textTraditional":"其在道也，曰餘食贅形。物或惡之，故有道者不處。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"kỳ tại đạo dã， viết dư thực chuyết hình。 vật hoặc ố chi， cố hữu đạo giả bất xử。","pinyinReading":"qí zài dào yě， yuē yú shí zhuì xíng。 wù huò wù zhī， gù yǒu dào zhě bù chǔ。","translation":"Đối với Đạo, gọi là thức ăn thừa, bướu thịt. Vật đều ghét chúng, nên người có Đạo không ở đó.","textSimplified":"其在道也，曰余食赘形。物或恶之，故有道者不处。"},

  {"id":"snt_ch_work_ddk_25_1","chapterId":"ch_work_ddk_25","textTraditional":"有物混成，先天地生。寂兮寥兮，獨立而不改，周行而不殆，可以為天地母。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"hữu vật hỗn thành， tiên thiên địa sinh。 tịch hề liêu hề， độc lập nhi bất cải， chu hành nhi bất đãi， khả dĩ vi thiên địa mẫu。","pinyinReading":"yǒu wù hùn chéng， xiān tiān dì shēng。 jì xī liáo xī， dú lì ér bù gǎi， zhōu xíng ér bù dài， kě yǐ wéi tiān dì mǔ。","translation":"Có vật hỗn độn mà thành, sinh trước trời đất. Lặng lẽ thay, trống trải thay, đứng một mình mà không đổi, vận hành khắp nơi mà không mỏi, có thể làm mẹ trời đất.","textSimplified":"有物混成，先天地生。寂兮寥兮，独立而不改，周行而不殆，可以为天地母。"},
  {"id":"snt_ch_work_ddk_25_2","chapterId":"ch_work_ddk_25","textTraditional":"吾不知其名，強字之曰道，強為之名曰大。大曰逝，逝曰遠，遠曰反。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"ngô bất tri kỳ danh， cưỡng tự chi viết đạo， cưỡng vi chi danh viết đại。 đại viết thệ， thệ viết viễn， viễn viết phản。","pinyinReading":"wú bù zhī qí míng， qiǎng zì zhī yuē dào， qiǎng wéi zhī míng yuē dà。 dà yuē shì， shì yuē yuǎn， yuǎn yuē fǎn。","translation":"Ta không biết tên nó, gượng đặt chữ gọi là Đạo, gượng đặt tên gọi là Lớn. Lớn thì đi, đi thì xa, xa thì quay về.","textSimplified":"吾不知其名，强字之曰道，强为之名曰大。大曰逝，逝曰远，远曰反。"},
  {"id":"snt_ch_work_ddk_25_3","chapterId":"ch_work_ddk_25","textTraditional":"故道大，天大，地大，人亦大。域中有四大，而人居其一焉。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"cố đạo đại， thiên đại， địa đại， nhân diệc đại。 vực trung hữu tứ đại， nhi nhân cư kỳ nhất yên。","pinyinReading":"gù dào dà， tiān dà， dì dà， rén yì dà。 yù zhōng yǒu sì dà， ér rén jū qí yī yān。","translation":"Cho nên Đạo lớn, trời lớn, đất lớn, người cũng lớn. Trong cõi có bốn cái lớn, mà người chiếm một trong đó."},
  {"id":"snt_ch_work_ddk_25_4","chapterId":"ch_work_ddk_25","textTraditional":"人法地，地法天，天法道，道法自然。","sentenceOrder":4,"paragraphGroup":2,"hanVietReading":"nhân pháp địa， địa pháp thiên， thiên pháp đạo， đạo pháp tự nhiên。","pinyinReading":"rén fǎ dì， dì fǎ tiān， tiān fǎ dào， dào fǎ zì rán。","translation":"Người bắt chước đất, đất bắt chước trời, trời bắt chước Đạo, Đạo bắt chước tự nhiên."},

  {"id":"snt_ch_work_ddk_26_1","chapterId":"ch_work_ddk_26","textTraditional":"重為輕根，靜為躁君。是以聖人終日行不離輜重。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"trọng vi khinh căn， tĩnh vi táo quân。 thị dĩ thánh nhân chung nhật hành bất ly tri trọng。","pinyinReading":"zhòng wéi qīng gēn， jìng wéi zào jūn。 shì yǐ shèng rén zhōng rì xíng bù lí zī zhòng。","translation":"Nặng là gốc của nhẹ, tĩnh là chủ của nóng nảy. Vì thế thánh nhân suốt ngày đi không rời xe hành lý.","textSimplified":"重为轻根，静为躁君。是以圣人终日行不离辎重。"},
  {"id":"snt_ch_work_ddk_26_2","chapterId":"ch_work_ddk_26","textTraditional":"雖有榮觀，燕處超然。奈何萬乘之主，而以身輕天下？","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"tuy hữu vinh quan， yến xử siêu nhiên。 nại hà vạn thừa chi chủ， nhi dĩ thân khinh thiên hạ？","pinyinReading":"suī yǒu róng guān， yàn chǔ chāo rán。 nài hé wàn shèng zhī zhǔ， ér yǐ shēn qīng tiān xià？","translation":"Tuy có cảnh vinh hoa lộng lẫy, vẫn an nhiên tự tại. Sao bậc vạn cỗ xe (thiên tử) lại lấy thân mình coi nhẹ thiên hạ?","textSimplified":"虽有荣观，燕处超然。奈何万乘之主，而以身轻天下？"},
  {"id":"snt_ch_work_ddk_26_3","chapterId":"ch_work_ddk_26","textTraditional":"輕則失根，躁則失君。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"khinh tắc thất căn， táo tắc thất quân。","pinyinReading":"qīng zé shī gēn， zào zé shī jūn。","translation":"Nhẹ thì mất gốc, nóng nảy thì mất chủ.","textSimplified":"轻则失根，躁则失君。"},

  {"id":"snt_ch_work_ddk_27_1","chapterId":"ch_work_ddk_27","textTraditional":"善行無轍迹，善言無瑕讁，善數不用籌策。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thiện hành vô triệt tích， thiện ngôn vô hà trích， thiện số bất dụng trù sách。","pinyinReading":"shàn xíng wú zhé jì， shàn yán wú xiá zhé， shàn shù bù yòng chóu cè。","translation":"Đi giỏi thì không để lại dấu vết, nói giỏi thì không sai sót, tính giỏi thì không dùng que tính.","textSimplified":"善行无辙迹，善言无瑕谪，善数不用筹策。"},
  {"id":"snt_ch_work_ddk_27_2","chapterId":"ch_work_ddk_27","textTraditional":"善閉無關楗而不可開，善結無繩約而不可解。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"thiện bế vô quan kiện nhi bất khả khai， thiện kết vô thằng ước nhi bất khả giải。","pinyinReading":"shàn bì wú guān jiàn ér bù kě kāi， shàn jié wú shéng yuē ér bù kě jiě。","translation":"Đóng giỏi thì không then khóa mà không mở được, buộc giỏi thì không dây thừng mà không tháo được.","textSimplified":"善闭无关楗而不可开，善结无绳约而不可解。"},
  {"id":"snt_ch_work_ddk_27_3","chapterId":"ch_work_ddk_27","textTraditional":"是以聖人常善救人，故無棄人；常善救物，故無棄物，是謂襲明。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"thị dĩ thánh nhân thường thiện cứu nhân， cố vô khí nhân； thường thiện cứu vật， cố vô khí vật， thị vị tập minh。","pinyinReading":"shì yǐ shèng rén cháng shàn jiù rén， gù wú qì rén； cháng shàn jiù wù， gù wú qì wù， shì wèi xí míng。","translation":"Vì thế thánh nhân luôn khéo cứu người, nên không bỏ ai; luôn khéo cứu vật, nên không bỏ vật nào — đó gọi là thừa kế sự sáng suốt.","textSimplified":"是以圣人常善救人，故无弃人；常善救物，故无弃物，是谓袭明。"},
  {"id":"snt_ch_work_ddk_27_4","chapterId":"ch_work_ddk_27","textTraditional":"故善人者，不善人之師；不善人者，善人之資。不貴其師，不愛其資，雖智大迷，是謂要妙。","sentenceOrder":4,"paragraphGroup":2,"hanVietReading":"cố thiện nhân giả， bất thiện nhân chi sư； bất thiện nhân giả， thiện nhân chi tư。 bất quý kỳ sư， bất ái kỳ tư， tuy trí đại mê， thị vị yếu diệu。","pinyinReading":"gù shàn rén zhě， bù shàn rén zhī shī； bù shàn rén zhě， shàn rén zhī zī。 bù guì qí shī， bù ài qí zī， suī zhì dà mí， shì wèi yào miào。","translation":"Cho nên người thiện là thầy của người bất thiện; người bất thiện là tài liệu học hỏi của người thiện. Không quý thầy, không yêu tài liệu, tuy thông minh cũng đại mê muội — đó là điều huyền diệu trọng yếu.","textSimplified":"故善人者，不善人之师；不善人者，善人之资。不贵其师，不爱其资，虽智大迷，是谓要妙。"},

  {"id":"snt_ch_work_ddk_28_1","chapterId":"ch_work_ddk_28","textTraditional":"知其雄，守其雌，為天下谿。為天下谿，常德不離，復歸於嬰兒。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"tri kỳ hùng， thủ kỳ thư， vi thiên hạ khê。 vi thiên hạ khê， thường đức bất ly， phục quy ư anh nhi。","pinyinReading":"zhī qí xióng， shǒu qí cí， wéi tiān xià xī。 wéi tiān xià xī， cháng dé bù lí， fù guī yú yīng ér。","translation":"Biết mạnh mà giữ mềm, làm khe suối cho thiên hạ. Làm khe suối cho thiên hạ, đức thường không rời, trở về trẻ sơ sinh.","textSimplified":"知其雄，守其雌，为天下溪。为天下溪，常德不离，复归于婴儿。"},
  {"id":"snt_ch_work_ddk_28_2","chapterId":"ch_work_ddk_28","textTraditional":"知其白，守其黑，為天下式。為天下式，常德不忒，復歸於無極。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"tri kỳ bạch， thủ kỳ hắc， vi thiên hạ thức。 vi thiên hạ thức， thường đức bất thắc， phục quy ư vô cực。","pinyinReading":"zhī qí bái， shǒu qí hēi， wéi tiān xià shì。 wéi tiān xià shì， cháng dé bù tè， fù guī yú wú jí。","translation":"Biết trắng mà giữ đen, làm khuôn mẫu cho thiên hạ. Làm khuôn mẫu cho thiên hạ, đức thường không sai lệch, trở về vô cực.","textSimplified":"知其白，守其黑，为天下式。为天下式，常德不忒，复归于无极。"},
  {"id":"snt_ch_work_ddk_28_3","chapterId":"ch_work_ddk_28","textTraditional":"知其榮，守其辱，為天下谷。為天下谷，常德乃足，復歸於樸。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"tri kỳ vinh， thủ kỳ nhục， vi thiên hạ cốc。 vi thiên hạ cốc， thường đức nãi túc， phục quy ư phác。","pinyinReading":"zhī qí róng， shǒu qí rǔ， wéi tiān xià gǔ。 wéi tiān xià gǔ， cháng dé nǎi zú， fù guī yú pǔ。","translation":"Biết vinh mà giữ nhục, làm thung lũng cho thiên hạ. Làm thung lũng cho thiên hạ, đức thường mới đủ, trở về mộc mạc.","textSimplified":"知其荣，守其辱，为天下谷。为天下谷，常德乃足，复归于朴。"},
  {"id":"snt_ch_work_ddk_28_4","chapterId":"ch_work_ddk_28","textTraditional":"樸散則為器，聖人用之則為官長。故大制不割。","sentenceOrder":4,"paragraphGroup":2,"hanVietReading":"phác tán tắc vi khí， thánh nhân dụng chi tắc vi quan trưởng。 cố đại chế bất cát。","pinyinReading":"pǔ sàn zé wéi qì， shèng rén yòng zhī zé wéi guān zhǎng。 gù dà zhì bù gē。","translation":"Mộc mạc tản ra thì thành đồ dùng, thánh nhân dùng thì thành bậc đứng đầu. Cho nên phép chế lớn không chia cắt.","textSimplified":"朴散则为器，圣人用之则为官长。故大制不割。"},

  {"id":"snt_ch_work_ddk_29_1","chapterId":"ch_work_ddk_29","textTraditional":"將欲取天下而為之，吾見其不得已。天下神器，不可為也，不可執也。為者敗之，執者失之。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"tương dục thủ thiên hạ nhi vi chi， ngô kiến kỳ bất đắc dĩ。 thiên hạ thần khí， bất khả vi dã， bất khả chấp dã。 vi giả bại chi， chấp giả thất chi。","pinyinReading":"jiāng yù qǔ tiān xià ér wéi zhī， wú jiàn qí bù dé yǐ。 tiān xià shén qì， bù kě wéi yě， bù kě zhí yě。 wéi zhě bài zhī， zhí zhě shī zhī。","translation":"Muốn lấy thiên hạ mà cưỡng làm, ta thấy sẽ không được. Thiên hạ là vật thần diệu, không thể cưỡng làm, không thể nắm giữ. Cưỡng làm thì hỏng, nắm giữ thì mất.","textSimplified":"将欲取天下而为之，吾见其不得已。天下神器，不可为也，不可执也。为者败之，执者失之。"},
  {"id":"snt_ch_work_ddk_29_2","chapterId":"ch_work_ddk_29","textTraditional":"故物或行或隨，或歔或吹，或強或羸，或載或隳。是以聖人去甚，去奢，去泰。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"cố vật hoặc hành hoặc tùy， hoặc hư hoặc xuy， hoặc cường hoặc luy， hoặc tái hoặc huy。 thị dĩ thánh nhân khứ thậm， khứ xa， khứ thái。","pinyinReading":"gù wù huò xíng huò suí， huò xū huò chuī， huò qiáng huò léi， huò zài huò huī。 shì yǐ shèng rén qù shèn， qù shē， qù tài。","translation":"Cho nên vật hoặc đi hoặc theo, hoặc hà hơi nóng hoặc thổi hơi lạnh, hoặc mạnh hoặc yếu, hoặc giữ yên hoặc đổ vỡ. Vì thế thánh nhân bỏ cái thái quá, bỏ xa xỉ, bỏ cao ngạo.","textSimplified":"故物或行或随，或嘘或吹，或强或羸，或载或隳。是以圣人去甚，去奢，去泰。"},

  {"id":"snt_ch_work_ddk_30_1","chapterId":"ch_work_ddk_30","textTraditional":"以道佐人主者，不以兵強天下。其事好還。師之所處，荊棘生焉。大軍之後，必有凶年。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"dĩ đạo tá nhân chủ giả， bất dĩ binh cường thiên hạ。 kỳ sự hiếu hoàn。 sư chi sở xử， kinh cức sinh yên。 đại quân chi hậu， tất hữu hung niên。","pinyinReading":"yǐ dào zuǒ rén zhǔ zhě， bù yǐ bīng qiáng tiān xià。 qí shì hǎo huán。 shī zhī suǒ chǔ， jīng jí shēng yān。 dà jūn zhī hòu， bì yǒu xiōng nián。","translation":"Người lấy Đạo giúp vua thì không dùng binh lực để uy hiếp thiên hạ. Việc ấy dễ gây hậu quả. Quân đội đi qua, gai góc mọc lên. Sau trận chiến lớn, tất có năm mất mùa.","textSimplified":"以道佐人主者，不以兵强天下。其事好还。师之所处，荆棘生焉。大军之后，必有凶年。"},
  {"id":"snt_ch_work_ddk_30_2","chapterId":"ch_work_ddk_30","textTraditional":"善有果而已，不敢以取強。果而勿矜，果而勿伐，果而勿驕，果而不得已，果而勿強。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thiện hữu quả nhi dĩ， bất cảm dĩ thủ cường。 quả nhi vật căng， quả nhi vật phạt， quả nhi vật kiêu， quả nhi bất đắc dĩ， quả nhi vật cường。","pinyinReading":"shàn yǒu guǒ ér yǐ， bù gǎn yǐ qǔ qiáng。 guǒ ér wù jīn， guǒ ér wù fá， guǒ ér wù jiāo， guǒ ér bù dé yǐ， guǒ ér wù qiáng。","translation":"Giỏi thì có kết quả rồi thôi, không dám lấy để mạnh. Đạt kết quả mà đừng kiêu, đạt kết quả mà đừng khoe, đạt kết quả mà đừng kiêu ngạo, đạt kết quả là bất đắc dĩ, đạt kết quả mà đừng cưỡng.","textSimplified":"善有果而已，不敢以取强。果而勿矜，果而勿伐，果而勿骄，果而不得已，果而勿强。"},
  {"id":"snt_ch_work_ddk_30_3","chapterId":"ch_work_ddk_30","textTraditional":"物壯則老，是謂不道，不道早已。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"vật tráng tắc lão， thị vị bất đạo， bất đạo tảo dĩ。","pinyinReading":"wù zhuàng zé lǎo， shì wèi bù dào， bù dào zǎo yǐ。","translation":"Vật mạnh rồi già đi, đó gọi là trái Đạo, trái Đạo thì sớm tàn.","textSimplified":"物壮则老，是谓不道，不道早已。"},

  {"id":"snt_ch_work_ddk_31_1","chapterId":"ch_work_ddk_31","textTraditional":"夫兵者，不祥之器，物或惡之，故有道者不處。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"phù binh giả， bất tường chi khí， vật hoặc ố chi， cố hữu đạo giả bất xử。","pinyinReading":"fú bīng zhě， bù xiáng zhī qì， wù huò wù zhī， gù yǒu dào zhě bù chǔ。","translation":"Binh khí là vật không lành, vạn vật ghét chúng, nên người có Đạo không dùng."},
  {"id":"snt_ch_work_ddk_31_2","chapterId":"ch_work_ddk_31","textTraditional":"君子居則貴左，用兵則貴右。兵者不祥之器，非君子之器，不得已而用之，恬淡為上。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"quân tử cư tắc quý tả， dụng binh tắc quý hữu。 binh giả bất tường chi khí， phi quân tử chi khí， bất đắc dĩ nhi dụng chi， điềm đạm vi thượng。","pinyinReading":"jūn zǐ jū zé guì zuǒ， yòng bīng zé guì yòu。 bīng zhě bù xiáng zhī qì， fēi jūn zǐ zhī qì， bù dé yǐ ér yòng zhī， tián dàn wéi shàng。","translation":"Quân tử ở thì quý bên trái, dùng binh thì quý bên phải. Binh khí là vật không lành, không phải đồ của quân tử, bất đắc dĩ mới dùng, điềm đạm là hơn.","textSimplified":"君子居则贵左，用兵则贵右。兵者不祥之器，非君子之器，不得已而用之，恬淡为上。"},
  {"id":"snt_ch_work_ddk_31_3","chapterId":"ch_work_ddk_31","textTraditional":"勝而不美，而美之者，是樂殺人。夫樂殺人者，則不可得志於天下矣。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"thắng nhi bất mỹ， nhi mỹ chi giả， thị lạc sát nhân。 phù lạc sát nhân giả， tắc bất khả đắc chí ư thiên hạ hĩ。","pinyinReading":"shèng ér bù měi， ér měi zhī zhě， shì lè shā rén。 fú lè shā rén zhě， zé bù kě dé zhì yú tiān xià yǐ。","translation":"Thắng mà không lấy làm đẹp; ai lấy làm đẹp là thích giết người. Kẻ thích giết người thì không thể đắc chí trong thiên hạ.","textSimplified":"胜而不美，而美之者，是乐杀人。夫乐杀人者，则不可得志于天下矣。"},
  {"id":"snt_ch_work_ddk_31_4","chapterId":"ch_work_ddk_31","textTraditional":"吉事尚左，凶事尚右。偏將軍居左，上將軍居右，言以喪禮處之。殺人之衆，以悲哀泣之，戰勝以喪禮處之。","sentenceOrder":4,"paragraphGroup":2,"hanVietReading":"cát sự thượng tả， hung sự thượng hữu。 thiên tướng quân cư tả， thượng tướng quân cư hữu， ngôn dĩ tang lễ xử chi。 sát nhân chi chúng， dĩ bi ai khấp chi， chiến thắng dĩ tang lễ xử chi。","pinyinReading":"jí shì shàng zuǒ， xiōng shì shàng yòu。 piān jiāng jūn jū zuǒ， shàng jiāng jūn jū yòu， yán yǐ sāng lǐ chǔ zhī。 shā rén zhī zhòng， yǐ bēi āi qì zhī， zhàn shèng yǐ sāng lǐ chǔ zhī。","translation":"Việc lành chuộng bên trái, việc dữ chuộng bên phải. Phó tướng đứng bên trái, thượng tướng đứng bên phải, nghĩa là lấy tang lễ mà xử. Giết người nhiều thì lấy bi ai mà khóc, chiến thắng thì lấy tang lễ mà xử.","textSimplified":"吉事尚左，凶事尚右。偏将军居左，上将军居右，言以丧礼处之。杀人之众，以悲哀泣之，战胜以丧礼处之。"},

  {"id":"snt_ch_work_ddk_32_1","chapterId":"ch_work_ddk_32","textTraditional":"道常無名，樸雖小，天下莫能臣。侯王若能守之，萬物將自賓。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"đạo thường vô danh， phác tuy tiểu， thiên hạ mạc năng thần。 hầu vương nhược năng thủ chi， vạn vật tương tự tân。","pinyinReading":"dào cháng wú míng， pǔ suī xiǎo， tiān xià mò néng chén。 hóu wáng ruò néng shǒu zhī， wàn wù jiāng zì bīn。","translation":"Đạo thường không tên, mộc mạc tuy nhỏ nhưng thiên hạ không ai bắt phục được. Vua chúa nếu giữ được nó, muôn vật sẽ tự quy phục.","textSimplified":"道常无名，朴虽小，天下莫能臣。侯王若能守之，万物将自宾。"},
  {"id":"snt_ch_work_ddk_32_2","chapterId":"ch_work_ddk_32","textTraditional":"天地相合，以降甘露，民莫之令而自均。始制有名，名亦既有，夫亦將知止，知止可以不殆。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thiên địa tương hợp， dĩ giáng cam lộ， dân mạc chi lệnh nhi tự quân。 thủy chế hữu danh， danh diệc ký hữu， phù diệc tương tri chỉ， tri chỉ khả dĩ bất đãi。","pinyinReading":"tiān dì xiāng hé， yǐ jiàng gān lù， mín mò zhī lìng ér zì jūn。 shǐ zhì yǒu míng， míng yì jì yǒu， fú yì jiāng zhī zhǐ， zhī zhǐ kě yǐ bù dài。","translation":"Trời đất giao hòa, ban sương ngọt, dân không ai bảo mà tự đều. Khi bắt đầu chế tác thì có tên, tên đã có thì nên biết dừng, biết dừng thì không nguy.","textSimplified":"天地相合，以降甘露，民莫之令而自均。始制有名，名亦既有，夫亦将知止，知止可以不殆。"},
  {"id":"snt_ch_work_ddk_32_3","chapterId":"ch_work_ddk_32","textTraditional":"譬道之在天下，猶川谷之於江海。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"thí đạo chi tại thiên hạ， do xuyên cốc chi ư giang hải。","pinyinReading":"pì dào zhī zài tiān xià， yóu chuān gǔ zhī yú jiāng hǎi。","translation":"Ví Đạo ở trong thiên hạ, như khe suối đổ về sông biển.","textSimplified":"譬道之在天下，犹川谷之于江海。"},

  {"id":"snt_ch_work_ddk_33_1","chapterId":"ch_work_ddk_33","textTraditional":"知人者智，自知者明。勝人者有力，自勝者強。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"tri nhân giả trí， tự tri giả minh。 thắng nhân giả hữu lực， tự thắng giả cường。","pinyinReading":"zhī rén zhě zhì， zì zhī zhě míng。 shèng rén zhě yǒu lì， zì shèng zhě qiáng。","translation":"Biết người là trí, tự biết mình là sáng suốt. Thắng người là có sức, tự thắng mình là mạnh mẽ.","textSimplified":"知人者智，自知者明。胜人者有力，自胜者强。"},
  {"id":"snt_ch_work_ddk_33_2","chapterId":"ch_work_ddk_33","textTraditional":"知足者富，強行者有志。不失其所者久，死而不亡者壽。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"tri túc giả phú， cưỡng hành giả hữu chí。 bất thất kỳ sở giả cửu， tử nhi bất vong giả thọ。","pinyinReading":"zhī zú zhě fù， qiǎng xíng zhě yǒu zhì。 bù shī qí suǒ zhě jiǔ， sǐ ér bù wáng zhě shòu。","translation":"Biết đủ là giàu, gắng sức làm là có chí. Không mất chỗ đứng thì lâu dài, chết mà không mất thì trường thọ.","textSimplified":"知足者富，强行者有志。不失其所者久，死而不亡者寿。"},

  {"id":"snt_ch_work_ddk_34_1","chapterId":"ch_work_ddk_34","textTraditional":"大道汎兮，其可左右。萬物恃之以生而不辭，功成而不有。衣養萬物而不為主。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"đại đạo phiếm hề， kỳ khả tả hữu。 vạn vật thị chi dĩ sinh nhi bất từ， công thành nhi bất hữu。 y dưỡng vạn vật nhi bất vi chủ。","pinyinReading":"dà dào fàn xī， qí kě zuǒ yòu。 wàn wù shì zhī yǐ shēng ér bù cí， gōng chéng ér bù yǒu。 yī yǎng wàn wù ér bù wéi zhǔ。","translation":"Đại Đạo tràn lan, có thể qua trái qua phải. Muôn vật nhờ nó mà sinh mà không từ chối, công thành mà không chiếm hữu. Nuôi dưỡng muôn vật mà không làm chủ.","textSimplified":"大道泛兮，其可左右。万物恃之以生而不辞，功成而不有。衣养万物而不为主。"},
  {"id":"snt_ch_work_ddk_34_2","chapterId":"ch_work_ddk_34","textTraditional":"常無欲，可名於小；萬物歸焉而不為主，可名為大。以其終不自為大，故能成其大。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thường vô dục， khả danh ư tiểu； vạn vật quy yên nhi bất vi chủ， khả danh vi đại。 dĩ kỳ chung bất tự vi đại， cố năng thành kỳ đại。","pinyinReading":"cháng wú yù， kě míng yú xiǎo； wàn wù guī yān ér bù wéi zhǔ， kě míng wéi dà。 yǐ qí zhōng bù zì wéi dà， gù néng chéng qí dà。","translation":"Thường không ham muốn, có thể gọi là nhỏ; muôn vật quay về mà không làm chủ, có thể gọi là lớn. Vì cuối cùng không tự cho mình lớn, nên mới thành được cái lớn.","textSimplified":"常无欲，可名于小；万物归焉而不为主，可名为大。以其终不自为大，故能成其大。"},

  {"id":"snt_ch_work_ddk_35_1","chapterId":"ch_work_ddk_35","textTraditional":"執大象，天下往。往而不害，安平泰。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"chấp đại tượng， thiên hạ vãng。 vãng nhi bất hại， an bình thái。","pinyinReading":"zhí dà xiàng， tiān xià wǎng。 wǎng ér bù hài， ān píng tài。","translation":"Nắm giữ hình tượng lớn (Đạo), thiên hạ đều quy về. Quy về mà không hại, thì an bình thái hòa."},
  {"id":"snt_ch_work_ddk_35_2","chapterId":"ch_work_ddk_35","textTraditional":"樂與餌，過客止。道之出口，淡乎其無味，視之不足見，聽之不足聞，用之不足既。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"nhạc dữ nhị， quá khách chỉ。 đạo chi xuất khẩu， đạm hồ kỳ vô vị， thị chi bất túc kiến， thính chi bất túc văn， dụng chi bất túc ký。","pinyinReading":"yuè yǔ ěr， guò kè zhǐ。 dào zhī chū kǒu， dàn hū qí wú wèi， shì zhī bù zú jiàn， tīng zhī bù zú wén， yòng zhī bù zú jì。","translation":"Nhạc và mồi, khách qua đường dừng lại. Đạo nói ra thì nhạt nhẽo vô vị, nhìn thì không đủ thấy, nghe thì không đủ nghe, dùng thì không bao giờ hết.","textSimplified":"乐与饵，过客止。道之出口，淡乎其无味，视之不足见，听之不足闻，用之不足既。"},

  {"id":"snt_ch_work_ddk_36_1","chapterId":"ch_work_ddk_36","textTraditional":"將欲歙之，必固張之；將欲弱之，必固強之；將欲廢之，必固興之；將欲取之，必固與之。是謂微明。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"tương dục hấp chi， tất cố trương chi； tương dục nhược chi， tất cố cường chi； tương dục phế chi， tất cố hưng chi； tương dục thủ chi， tất cố dữ chi。 thị vị vi minh。","pinyinReading":"jiāng yù xì zhī， bì gù zhāng zhī； jiāng yù ruò zhī， bì gù qiáng zhī； jiāng yù fèi zhī， bì gù xīng zhī； jiāng yù qǔ zhī， bì gù yǔ zhī。 shì wèi wēi míng。","translation":"Muốn thu lại, tất phải mở ra; muốn làm yếu, tất phải làm mạnh; muốn bỏ đi, tất phải dựng lên; muốn lấy đi, tất phải cho. Đó gọi là sáng suốt tinh vi.","textSimplified":"将欲歙之，必固张之；将欲弱之，必固强之；将欲废之，必固兴之；将欲取之，必固与之。是谓微明。"},
  {"id":"snt_ch_work_ddk_36_2","chapterId":"ch_work_ddk_36","textTraditional":"柔弱勝剛強。魚不可脫於淵，國之利器不可以示人。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"nhu nhược thắng cương cường。 ngư bất khả thoát ư uyên， quốc chi lợi khí bất khả dĩ thị nhân。","pinyinReading":"róu ruò shèng gāng qiáng。 yú bù kě tuō yú yuān， guó zhī lì qì bù kě yǐ shì rén。","translation":"Mềm yếu thắng cứng mạnh. Cá không nên rời khỏi vực sâu, lợi khí của nước không nên phô cho người xem.","textSimplified":"柔弱胜刚强。鱼不可脱于渊，国之利器不可以示人。"},

  {"id":"snt_ch_work_ddk_37_1","chapterId":"ch_work_ddk_37","textTraditional":"道常無為而無不為。侯王若能守之，萬物將自化。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"đạo thường vô vi nhi vô bất vi。 hầu vương nhược năng thủ chi， vạn vật tương tự hóa。","pinyinReading":"dào cháng wú wéi ér wú bù wéi。 hóu wáng ruò néng shǒu zhī， wàn wù jiāng zì huà。","translation":"Đạo thường vô vi mà không gì không làm được. Vua chúa nếu giữ được nó, muôn vật sẽ tự biến hóa.","textSimplified":"道常无为而无不为。侯王若能守之，万物将自化。"},
  {"id":"snt_ch_work_ddk_37_2","chapterId":"ch_work_ddk_37","textTraditional":"化而欲作，吾將鎮之以無名之樸。鎮之以無名之樸，夫亦將不欲。不欲以靜，天下將自正。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"hóa nhi dục tác， ngô tương trấn chi dĩ vô danh chi phác。 trấn chi dĩ vô danh chi phác， phù diệc tương bất dục。 bất dục dĩ tĩnh， thiên hạ tương tự chính。","pinyinReading":"huà ér yù zuò， wú jiāng zhèn zhī yǐ wú míng zhī pǔ。 zhèn zhī yǐ wú míng zhī pǔ， fú yì jiāng bù yù。 bù yù yǐ jìng， tiān xià jiāng zì zhèng。","translation":"Biến hóa mà muốn dấy lên, ta sẽ trấn áp bằng cái mộc mạc vô danh. Trấn áp bằng mộc mạc vô danh thì cũng sẽ không ham muốn. Không ham muốn mà tĩnh lặng, thiên hạ sẽ tự ổn định.","textSimplified":"化而欲作，吾将镇之以无名之朴。镇之以无名之朴，夫亦将不欲。不欲以静，天下将自正。"},

  {"id":"snt_ch_work_ddk_38_1","chapterId":"ch_work_ddk_38","textTraditional":"上德不德，是以有德；下德不失德，是以無德。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thượng đức bất đức， thị dĩ hữu đức； hạ đức bất thất đức， thị dĩ vô đức。","pinyinReading":"shàng dé bù dé， shì yǐ yǒu dé； xià dé bù shī dé， shì yǐ wú dé。","translation":"Đức cao không cố giữ đức, nên mới có đức; đức thấp không muốn mất đức, nên không có đức.","textSimplified":"上德不德，是以有德；下德不失德，是以无德。"},
  {"id":"snt_ch_work_ddk_38_2","chapterId":"ch_work_ddk_38","textTraditional":"上德無為而無以為；下德無為而有以為。上仁為之而無以為；上義為之而有以為。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"thượng đức vô vi nhi vô dĩ vi； hạ đức vô vi nhi hữu dĩ vi。 thượng nhân vi chi nhi vô dĩ vi； thượng nghĩa vi chi nhi hữu dĩ vi。","pinyinReading":"shàng dé wú wéi ér wú yǐ wéi； xià dé wú wéi ér yǒu yǐ wéi。 shàng rén wéi zhī ér wú yǐ wéi； shàng yì wéi zhī ér yǒu yǐ wéi。","translation":"Đức cao vô vi mà không có ý làm; đức thấp vô vi mà có ý làm. Nhân cao làm mà không có ý; nghĩa cao làm mà có ý.","textSimplified":"上德无为而无以为；下德无为而有以为。上仁为之而无以为；上义为之而有以为。"},
  {"id":"snt_ch_work_ddk_38_3","chapterId":"ch_work_ddk_38","textTraditional":"上禮為之而莫之應，則攘臂而扔之。故失道而後德，失德而後仁，失仁而後義，失義而後禮。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"thượng lễ vi chi nhi mạc chi ứng， tắc nhương tý nhi nhưng chi。 cố thất đạo nhi hậu đức， thất đức nhi hậu nhân， thất nhân nhi hậu nghĩa， thất nghĩa nhi hậu lễ。","pinyinReading":"shàng lǐ wéi zhī ér mò zhī yìng， zé rǎng bì ér réng zhī。 gù shī dào ér hòu dé， shī dé ér hòu rén， shī rén ér hòu yì， shī yì ér hòu lǐ。","translation":"Lễ cao làm mà không ai hưởng ứng, thì xắn tay áo mà ép buộc. Cho nên mất Đạo rồi mới có Đức, mất Đức rồi mới có Nhân, mất Nhân rồi mới có Nghĩa, mất Nghĩa rồi mới có Lễ.","textSimplified":"上礼为之而莫之应，则攘臂而扔之。故失道而后德，失德而后仁，失仁而后义，失义而后礼。"},
  {"id":"snt_ch_work_ddk_38_4","chapterId":"ch_work_ddk_38","textTraditional":"夫禮者，忠信之薄而亂之首。前識者，道之華而愚之始。是以大丈夫處其厚，不居其薄；處其實，不居其華。故去彼取此。","sentenceOrder":4,"paragraphGroup":2,"hanVietReading":"phù lễ giả， trung tín chi bạc nhi loạn chi thủ。 tiền thức giả， đạo chi hoa nhi ngu chi thủy。 thị dĩ đại trượng phu xử kỳ hậu， bất cư kỳ bạc； xử kỳ thực， bất cư kỳ hoa。 cố khứ bỉ thủ thử。","pinyinReading":"fú lǐ zhě， zhōng xìn zhī bó ér luàn zhī shǒu。 qián shí zhě， dào zhī huá ér yú zhī shǐ。 shì yǐ dà zhàng fū chǔ qí hòu， bù jū qí bó； chǔ qí shí， bù jū qí huá。 gù qù bǐ qǔ cǐ。","translation":"Lễ là chỗ trung tín mỏng manh và đầu mối của loạn. Kẻ tiên tri là hoa hòe của Đạo và khởi đầu của ngu. Vì thế đại trượng phu ở chỗ dày, không ở chỗ mỏng; ở chỗ thực, không ở chỗ hoa. Cho nên bỏ cái kia lấy cái này.","textSimplified":"夫礼者，忠信之薄而乱之首。前识者，道之华而愚之始。是以大丈夫处其厚，不居其薄；处其实，不居其华。故去彼取此。"},

  {"id":"snt_ch_work_ddk_39_1","chapterId":"ch_work_ddk_39","textTraditional":"昔之得一者：天得一以清，地得一以寧，神得一以靈，谷得一以盈，萬物得一以生，侯王得一以為天下正。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"tích chi đắc nhất giả： thiên đắc nhất dĩ thanh， địa đắc nhất dĩ ninh， thần đắc nhất dĩ linh， cốc đắc nhất dĩ doanh， vạn vật đắc nhất dĩ sinh， hầu vương đắc nhất dĩ vi thiên hạ chính。","pinyinReading":"xī zhī dé yī zhě： tiān dé yī yǐ qīng， dì dé yī yǐ níng， shén dé yī yǐ líng， gǔ dé yī yǐ yíng， wàn wù dé yī yǐ shēng， hóu wáng dé yī yǐ wéi tiān xià zhèng。","translation":"Xưa những cái được Một: trời được Một nên trong, đất được Một nên yên, thần được Một nên linh, hang được Một nên đầy, muôn vật được Một nên sinh, vua chúa được Một nên làm chuẩn mực thiên hạ.","textSimplified":"昔之得一者：天得一以清，地得一以宁，神得一以灵，谷得一以盈，万物得一以生，侯王得一以为天下正。"},
  {"id":"snt_ch_work_ddk_39_2","chapterId":"ch_work_ddk_39","textTraditional":"故貴以賤為本，高以下為基。是以侯王自稱孤、寡、不穀。此非以賤為本邪？非乎？","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"cố quý dĩ tiện vi bản， cao dĩ hạ vi cơ。 thị dĩ hầu vương tự xưng cô、 quả、 bất cốc。 thử phi dĩ tiện vi bản tà？ phi hồ？","pinyinReading":"gù guì yǐ jiàn wéi běn， gāo yǐ xià wéi jī。 shì yǐ hóu wáng zì chēng gū、 guǎ、 bù gǔ。 cǐ fēi yǐ jiàn wéi běn yé？ fēi hū？","translation":"Cho nên quý lấy hèn làm gốc, cao lấy thấp làm nền. Vì thế vua chúa tự xưng cô, quả, bất cốc (côi cút, thiếu thốn). Đó chẳng phải lấy hèn làm gốc sao?","textSimplified":"故贵以贱为本，高以下为基。是以侯王自称孤、寡、不谷。此非以贱为本邪？非乎？"},
  {"id":"snt_ch_work_ddk_39_3","chapterId":"ch_work_ddk_39","textTraditional":"故致數譽無譽。是故不欲琭琭如玉，珞珞如石。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"cố trí số dự vô dự。 thị cố bất dục lục lục như ngọc， lạc lạc như thạch。","pinyinReading":"gù zhì shù yù wú yù。 shì gù bù yù lù lù rú yù， luò luò rú shí。","translation":"Cho nên khen nhiều quá thì thành không được khen. Vì thế không muốn lấp lánh như ngọc, mà lầm lì như đá.","textSimplified":"故致数誉无誉。是故不欲琭琭如玉，珞珞如石。"},

  {"id":"snt_ch_work_ddk_40_1","chapterId":"ch_work_ddk_40","textTraditional":"反者道之動，弱者道之用。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"phản giả đạo chi động， nhược giả đạo chi dụng。","pinyinReading":"fǎn zhě dào zhī dòng， ruò zhě dào zhī yòng。","translation":"Quay ngược lại là sự vận động của Đạo, mềm yếu là công dụng của Đạo."},
  {"id":"snt_ch_work_ddk_40_2","chapterId":"ch_work_ddk_40","textTraditional":"天下萬物生於有，有生於無。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"thiên hạ vạn vật sinh ư hữu， hữu sinh ư vô。","pinyinReading":"tiān xià wàn wù shēng yú yǒu， yǒu shēng yú wú。","translation":"Muôn vật trong thiên hạ sinh từ Có, Có sinh từ Không.","textSimplified":"天下万物生于有，有生于无。"},

  {"id":"snt_ch_work_ddk_41_1","chapterId":"ch_work_ddk_41","textTraditional":"上士聞道，勤而行之；中士聞道，若存若亡；下士聞道，大笑之。不笑不足以為道。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thượng sĩ văn đạo， cần nhi hành chi； trung sĩ văn đạo， nhược tồn nhược vong； hạ sĩ văn đạo， đại tiếu chi。 bất tiếu bất túc dĩ vi đạo。","pinyinReading":"shàng shì wén dào， qín ér xíng zhī； zhōng shì wén dào， ruò cún ruò wáng； xià shì wén dào， dà xiào zhī。 bù xiào bù zú yǐ wéi dào。","translation":"Kẻ sĩ bậc cao nghe Đạo thì siêng năng thực hành; kẻ sĩ bậc trung nghe Đạo thì nửa tin nửa ngờ; kẻ sĩ bậc hạ nghe Đạo thì cười lớn. Không cười thì không đủ gọi là Đạo.","textSimplified":"上士闻道，勤而行之；中士闻道，若存若亡；下士闻道，大笑之。不笑不足以为道。"},
  {"id":"snt_ch_work_ddk_41_2","chapterId":"ch_work_ddk_41","textTraditional":"故建言有之：明道若昧，進道若退，夷道若纇。上德若谷，廣德若不足，建德若偷，質真若渝。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"cố kiến ngôn hữu chi： minh đạo nhược muội， tiến đạo nhược thoái， di đạo nhược lỗi。 thượng đức nhược cốc， quảng đức nhược bất túc， kiến đức nhược thâu， chất chân nhược du。","pinyinReading":"gù jiàn yán yǒu zhī： míng dào ruò mèi， jìn dào ruò tuì， yí dào ruò lèi。 shàng dé ruò gǔ， guǎng dé ruò bù zú， jiàn dé ruò tōu， zhì zhēn ruò yú。","translation":"Cho nên lời xưa có nói: Đạo sáng dường như tối, Đạo tiến dường như lùi, Đạo bằng dường như gồ ghề. Đức cao dường như thung lũng, đức rộng dường như thiếu, đức vững dường như lười, chất thật dường như thay đổi.","textSimplified":"故建言有之：明道若昧，进道若退，夷道若类。上德若谷，广德若不足，建德若偷，质真若渝。"},
  {"id":"snt_ch_work_ddk_41_3","chapterId":"ch_work_ddk_41","textTraditional":"大白若辱，大方無隅，大器晚成，大音希聲，大象無形。道隱無名。夫唯道，善貸且成。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"đại bạch nhược nhục， đại phương vô ngung， đại khí vãn thành， đại âm hi thanh， đại tượng vô hình。 đạo ẩn vô danh。 phù duy đạo， thiện thải thả thành。","pinyinReading":"dà bái ruò rǔ， dà fāng wú yú， dà qì wǎn chéng， dà yīn xī shēng， dà xiàng wú xíng。 dào yǐn wú míng。 fú wéi dào， shàn dài qiě chéng。","translation":"Trắng lớn dường như nhơ, vuông lớn thì không góc, đồ lớn thì muộn thành, tiếng lớn thì ít nghe, hình lớn thì không hình. Đạo ẩn không tên. Chỉ có Đạo là khéo cho và thành tựu.","textSimplified":"大白若辱，大方无隅，大器晚成，大音希声，大象无形。道隐无名。夫唯道，善贷且成。"},

  {"id":"snt_ch_work_ddk_42_1","chapterId":"ch_work_ddk_42","textTraditional":"道生一，一生二，二生三，三生萬物。萬物負陰而抱陽，沖氣以為和。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"đạo sinh nhất， nhất sinh nhị， nhị sinh tam， tam sinh vạn vật。 vạn vật phụ âm nhi bão dương， xung khí dĩ vi hòa。","pinyinReading":"dào shēng yī， yī shēng èr， èr shēng sān， sān shēng wàn wù。 wàn wù fù yīn ér bào yáng， chōng qì yǐ wéi hé。","translation":"Đạo sinh Một, Một sinh Hai, Hai sinh Ba, Ba sinh muôn vật. Muôn vật cõng Âm mà ôm Dương, khí xung hòa mà thành điều hòa.","textSimplified":"道生一，一生二，二生三，三生万物。万物负阴而抱阳，冲气以为和。"},
  {"id":"snt_ch_work_ddk_42_2","chapterId":"ch_work_ddk_42","textTraditional":"人之所惡，唯孤、寡、不穀，而王公以為稱。故物或損之而益，或益之而損。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"nhân chi sở ố， duy cô、 quả、 bất cốc， nhi vương công dĩ vi xưng。 cố vật hoặc tổn chi nhi ích， hoặc ích chi nhi tổn。","pinyinReading":"rén zhī suǒ wù， wéi gū、 guǎ、 bù gǔ， ér wáng gōng yǐ wéi chēng。 gù wù huò sǔn zhī ér yì， huò yì zhī ér sǔn。","translation":"Điều người ta ghét là cô, quả, bất cốc, nhưng vua chúa lại dùng để tự xưng. Cho nên vật có khi bớt mà thêm, có khi thêm mà bớt.","textSimplified":"人之所恶，唯孤、寡、不谷，而王公以为称。故物或损之而益，或益之而损。"},
  {"id":"snt_ch_work_ddk_42_3","chapterId":"ch_work_ddk_42","textTraditional":"人之所教，我亦教之。強梁者不得其死，吾將以為教父。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"nhân chi sở giáo， ngã diệc giáo chi。 cường lương giả bất đắc kỳ tử， ngô tương dĩ vi giáo phụ。","pinyinReading":"rén zhī suǒ jiào， wǒ yì jiào zhī。 qiáng liáng zhě bù dé qí sǐ， wú jiāng yǐ wéi jiào fù。","translation":"Điều người ta dạy, ta cũng dạy theo. Kẻ cứng cỏi hung hãn không được chết tốt, ta lấy đó làm lời dạy đầu tiên.","textSimplified":"人之所教，我亦教之。强梁者不得其死，吾将以为教父。"},

  {"id":"snt_ch_work_ddk_43_1","chapterId":"ch_work_ddk_43","textTraditional":"天下之至柔，馳騁天下之至堅。無有入無間，吾是以知無為之有益。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thiên hạ chi chí nhu， trì sính thiên hạ chi chí kiên。 vô hữu nhập vô gian， ngô thị dĩ tri vô vi chi hữu ích。","pinyinReading":"tiān xià zhī zhì róu， chí chěng tiān xià zhī zhì jiān。 wú yǒu rù wú jiān， wú shì yǐ zhī wú wéi zhī yǒu yì。","translation":"Cái mềm nhất thiên hạ xuyên suốt cái cứng nhất thiên hạ. Cái không có hình xen vào chỗ không kẽ hở, ta do đó mà biết vô vi là có ích.","textSimplified":"天下之至柔，驰骋天下之至坚。无有入无间，吾是以知无为之有益。"},
  {"id":"snt_ch_work_ddk_43_2","chapterId":"ch_work_ddk_43","textTraditional":"不言之教，無為之益，天下希及之。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"bất ngôn chi giáo， vô vi chi ích， thiên hạ hi cập chi。","pinyinReading":"bù yán zhī jiào， wú wéi zhī yì， tiān xià xī jí zhī。","translation":"Sự dạy không lời, lợi ích của vô vi, thiên hạ ít ai theo kịp."},

  {"id":"snt_ch_work_ddk_44_1","chapterId":"ch_work_ddk_44","textTraditional":"名與身孰親？身與貨孰多？得與亡孰病？","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"danh dữ thân thục thân？ thân dữ hóa thục đa？ đắc dữ vong thục bệnh？","pinyinReading":"míng yǔ shēn shú qīn？ shēn yǔ huò shú duō？ dé yǔ wáng shú bìng？","translation":"Danh tiếng và thân mình, cái nào gần hơn? Thân mình và của cải, cái nào nhiều hơn? Được và mất, cái nào khổ hơn?","textSimplified":"名与身孰亲？身与货孰多？得与亡孰病？"},
  {"id":"snt_ch_work_ddk_44_2","chapterId":"ch_work_ddk_44","textTraditional":"甚愛必大費，多藏必厚亡。故知足不辱，知止不殆，可以長久。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thậm ái tất đại phí， đa tàng tất hậu vong。 cố tri túc bất nhục， tri chỉ bất đãi， khả dĩ trường cửu。","pinyinReading":"shèn ài bì dà fèi， duō cáng bì hòu wáng。 gù zhī zú bù rǔ， zhī zhǐ bù dài， kě yǐ cháng jiǔ。","translation":"Yêu quá tất tốn nhiều, tích trữ nhiều tất mất lớn. Cho nên biết đủ thì không nhục, biết dừng thì không nguy, có thể lâu dài.","textSimplified":"甚爱必大费，多藏必厚亡。故知足不辱，知止不殆，可以长久。"},

  {"id":"snt_ch_work_ddk_45_1","chapterId":"ch_work_ddk_45","textTraditional":"大成若缺，其用不弊。大盈若沖，其用不窮。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"đại thành nhược khuyết， kỳ dụng bất tệ。 đại doanh nhược xung， kỳ dụng bất cùng。","pinyinReading":"dà chéng ruò quē， qí yòng bù bì。 dà yíng ruò chōng， qí yòng bù qióng。","translation":"Hoàn thành lớn dường như khiếm khuyết, nhưng dùng không hỏng. Đầy lớn dường như trống rỗng, nhưng dùng không cạn."},
  {"id":"snt_ch_work_ddk_45_2","chapterId":"ch_work_ddk_45","textTraditional":"大直若屈，大巧若拙，大辯若訥。靜勝躁，寒勝熱。清靜為天下正。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"đại trực nhược khuất， đại xảo nhược chuyết， đại biện nhược nột。 tĩnh thắng táo， hàn thắng nhiệt。 thanh tĩnh vi thiên hạ chính。","pinyinReading":"dà zhí ruò qū， dà qiǎo ruò zhuō， dà biàn ruò nè。 jìng shèng zào， hán shèng rè。 qīng jìng wéi tiān xià zhèng。","translation":"Thẳng lớn dường như cong, khéo lớn dường như vụng, hùng biện dường như ấp úng. Tĩnh thắng nóng nảy, lạnh thắng nóng. Thanh tĩnh làm chuẩn mực thiên hạ.","textSimplified":"大直若屈，大巧若拙，大辩若讷。静胜躁，寒胜热。清静为天下正。"},

  {"id":"snt_ch_work_ddk_46_1","chapterId":"ch_work_ddk_46","textTraditional":"天下有道，卻走馬以糞。天下無道，戎馬生於郊。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thiên hạ hữu đạo， khước tẩu mã dĩ phẩn。 thiên hạ vô đạo， nhung mã sinh ư giao。","pinyinReading":"tiān xià yǒu dào， què zǒu mǎ yǐ fèn。 tiān xià wú dào， róng mǎ shēng yú jiāo。","translation":"Thiên hạ có Đạo thì ngựa chiến lui về cày ruộng. Thiên hạ không có Đạo thì ngựa chiến sinh ngoài đồng.","textSimplified":"天下有道，却走马以粪。天下无道，戎马生于郊。"},
  {"id":"snt_ch_work_ddk_46_2","chapterId":"ch_work_ddk_46","textTraditional":"禍莫大於不知足，咎莫大於欲得。故知足之足，常足矣。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"họa mạc đại ư bất tri túc， cữu mạc đại ư dục đắc。 cố tri túc chi túc， thường túc hĩ。","pinyinReading":"huò mò dà yú bù zhī zú， jiù mò dà yú yù dé。 gù zhī zú zhī zú， cháng zú yǐ。","translation":"Họa không gì lớn bằng không biết đủ, lỗi không gì lớn bằng muốn được. Cho nên biết đủ là đủ thì luôn đủ."},

  {"id":"snt_ch_work_ddk_47_1","chapterId":"ch_work_ddk_47","textTraditional":"不出戶，知天下；不窺牖，見天道。其出彌遠，其知彌少。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"bất xuất hộ， tri thiên hạ； bất khuy dũ， kiến thiên đạo。 kỳ xuất di viễn， kỳ tri di thiểu。","pinyinReading":"bù chū hù， zhī tiān xià； bù kuī yǒu， jiàn tiān dào。 qí chū mí yuǎn， qí zhī mí shǎo。","translation":"Không ra khỏi cửa mà biết thiên hạ; không nhìn qua cửa sổ mà thấy đạo trời. Đi càng xa, biết càng ít.","textSimplified":"不出户，知天下；不窥牖，见天道。其出弥远，其知弥少。"},
  {"id":"snt_ch_work_ddk_47_2","chapterId":"ch_work_ddk_47","textTraditional":"是以聖人不行而知，不見而明，不為而成。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thị dĩ thánh nhân bất hành nhi tri， bất kiến nhi minh， bất vi nhi thành。","pinyinReading":"shì yǐ shèng rén bù xíng ér zhī， bù jiàn ér míng， bù wéi ér chéng。","translation":"Vì thế thánh nhân không đi mà biết, không nhìn mà sáng, không làm mà thành.","textSimplified":"是以圣人不行而知，不见而明，不为而成。"},

  {"id":"snt_ch_work_ddk_48_1","chapterId":"ch_work_ddk_48","textTraditional":"為學日益，為道日損。損之又損，以至於無為。無為而無不為。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"vi học nhật ích， vi đạo nhật tổn。 tổn chi hựu tổn， dĩ chí ư vô vi。 vô vi nhi vô bất vi。","pinyinReading":"wéi xué rì yì， wéi dào rì sǔn。 sǔn zhī yòu sǔn， yǐ zhì yú wú wéi。 wú wéi ér wú bù wéi。","translation":"Làm việc học thì ngày thêm, làm theo Đạo thì ngày bớt. Bớt rồi lại bớt, cho đến vô vi. Vô vi mà không gì không làm được.","textSimplified":"为学日益，为道日损。损之又损，以至于无为。无为而无不为。"},
  {"id":"snt_ch_work_ddk_48_2","chapterId":"ch_work_ddk_48","textTraditional":"取天下常以無事，及其有事，不足以取天下。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thủ thiên hạ thường dĩ vô sự， cập kỳ hữu sự， bất túc dĩ thủ thiên hạ。","pinyinReading":"qǔ tiān xià cháng yǐ wú shì， jí qí yǒu shì， bù zú yǐ qǔ tiān xià。","translation":"Lấy thiên hạ thường nhờ vô sự, đến khi hữu sự thì không đủ để lấy thiên hạ."},

  {"id":"snt_ch_work_ddk_49_1","chapterId":"ch_work_ddk_49","textTraditional":"聖人常無心，以百姓心為心。善者，吾善之；不善者，吾亦善之，德善。信者，吾信之；不信者，吾亦信之，德信。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thánh nhân thường vô tâm， dĩ bách tính tâm vi tâm。 thiện giả， ngô thiện chi； bất thiện giả， ngô diệc thiện chi， đức thiện。 tín giả， ngô tín chi； bất tín giả， ngô diệc tín chi， đức tín。","pinyinReading":"shèng rén cháng wú xīn， yǐ bǎi xìng xīn wéi xīn。 shàn zhě， wú shàn zhī； bù shàn zhě， wú yì shàn zhī， dé shàn。 xìn zhě， wú xìn zhī； bù xìn zhě， wú yì xìn zhī， dé xìn。","translation":"Thánh nhân thường không có lòng riêng, lấy lòng trăm họ làm lòng mình. Người thiện, ta thiện với họ; người bất thiện, ta cũng thiện với họ — ấy là đức thiện. Người tin, ta tin họ; người không tin, ta cũng tin họ — ấy là đức tín.","textSimplified":"圣人常无心，以百姓心为心。善者，吾善之；不善者，吾亦善之，德善。信者，吾信之；不信者，吾亦信之，德信。"},
  {"id":"snt_ch_work_ddk_49_2","chapterId":"ch_work_ddk_49","textTraditional":"聖人在天下，歙歙焉，為天下渾其心。百姓皆注其耳目，聖人皆孩之。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thánh nhân tại thiên hạ， hấp hấp yên， vi thiên hạ hỗn kỳ tâm。 bách tính giai chú kỳ nhĩ mục， thánh nhân giai hài chi。","pinyinReading":"shèng rén zài tiān xià， xì xì yān， wéi tiān xià hún qí xīn。 bǎi xìng jiē zhù qí ěr mù， shèng rén jiē hái zhī。","translation":"Thánh nhân ở trong thiên hạ thu mình lại, vì thiên hạ mà hỗn độn lòng mình. Trăm họ đều dồn tai mắt vào, thánh nhân đều coi họ như con trẻ.","textSimplified":"圣人在天下，歙歙焉，为天下浑其心。百姓皆注其耳目，圣人皆孩之。"},

  {"id":"snt_ch_work_ddk_50_1","chapterId":"ch_work_ddk_50","textTraditional":"出生入死。生之徒十有三，死之徒十有三，人之生動之於死地亦十有三。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"xuất sinh nhập tử。 sinh chi đồ thập hữu tam， tử chi đồ thập hữu tam， nhân chi sinh động chi ư tử địa diệc thập hữu tam。","pinyinReading":"chū shēng rù sǐ。 shēng zhī tú shí yǒu sān， sǐ zhī tú shí yǒu sān， rén zhī shēng dòng zhī yú sǐ dì yì shí yǒu sān。","translation":"Ra đời vào chết. Những người thuộc về sống là mười phần có ba; thuộc về chết mười phần có ba; người đang sống mà tự đi vào chỗ chết cũng mười phần có ba."},
  {"id":"snt_ch_work_ddk_50_2","chapterId":"ch_work_ddk_50","textTraditional":"夫何故？以其生生之厚。蓋聞善攝生者，陸行不遇兕虎，入軍不被甲兵。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"phù hà cố？ dĩ kỳ sinh sinh chi hậu。 cái văn thiện nhiếp sinh giả， lục hành bất ngộ tê hổ， nhập quân bất bị giáp binh。","pinyinReading":"fú hé gù？ yǐ qí shēng shēng zhī hòu。 gài wén shàn shè shēng zhě， lù xíng bù yù sì hǔ， rù jūn bù bèi jiǎ bīng。","translation":"Vì sao vậy? Vì ham sống quá đáng. Nghe nói người giỏi giữ gìn sự sống, đi trên đất liền không gặp tê giác hổ, vào quân đội không mang áo giáp binh khí.","textSimplified":"夫何故？以其生生之厚。盖闻善摄生者，陆行不遇兕虎，入军不被甲兵。"},
  {"id":"snt_ch_work_ddk_50_3","chapterId":"ch_work_ddk_50","textTraditional":"兕無所投其角，虎無所措其爪，兵無所容其刃。夫何故？以其無死地。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"tê vô sở đầu kỳ giác， hổ vô sở thố kỳ trảo， binh vô sở dung kỳ nhận。 phù hà cố？ dĩ kỳ vô tử địa。","pinyinReading":"sì wú suǒ tóu qí jiǎo， hǔ wú suǒ cuò qí zhǎo， bīng wú suǒ róng qí rèn。 fú hé gù？ yǐ qí wú sǐ dì。","translation":"Tê giác không chỗ húc sừng, hổ không chỗ vồ móng, binh khí không chỗ đâm lưỡi. Vì sao? Vì người ấy không có chỗ chết.","textSimplified":"兕无所投其角，虎无所措其爪，兵无所容其刃。夫何故？以其无死地。"},

  {"id":"snt_ch_work_ddk_51_1","chapterId":"ch_work_ddk_51","textTraditional":"道生之，德畜之，物形之，勢成之。是以萬物莫不尊道而貴德。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"đạo sinh chi， đức húc chi， vật hình chi， thế thành chi。 thị dĩ vạn vật mạc bất tôn đạo nhi quý đức。","pinyinReading":"dào shēng zhī， dé xù zhī， wù xíng zhī， shì chéng zhī。 shì yǐ wàn wù mò bù zūn dào ér guì dé。","translation":"Đạo sinh ra, Đức nuôi nấng, vật tạo hình, thế hoàn thành. Vì thế muôn vật không gì không tôn Đạo mà quý Đức.","textSimplified":"道生之，德畜之，物形之，势成之。是以万物莫不尊道而贵德。"},
  {"id":"snt_ch_work_ddk_51_2","chapterId":"ch_work_ddk_51","textTraditional":"道之尊，德之貴，夫莫之命而常自然。故道生之，德畜之，長之育之，亭之毒之，養之覆之。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"đạo chi tôn， đức chi quý， phù mạc chi mệnh nhi thường tự nhiên。 cố đạo sinh chi， đức húc chi， trưởng chi dục chi， đình chi độc chi， dưỡng chi phú chi。","pinyinReading":"dào zhī zūn， dé zhī guì， fú mò zhī mìng ér cháng zì rán。 gù dào shēng zhī， dé xù zhī， zhǎng zhī yù zhī， tíng zhī dú zhī， yǎng zhī fù zhī。","translation":"Đạo được tôn, Đức được quý, không ai ra lệnh mà tự nhiên vậy. Cho nên Đạo sinh ra, Đức nuôi nấng, nuôi lớn, chăm sóc, che chở.","textSimplified":"道之尊，德之贵，夫莫之命而常自然。故道生之，德畜之，长之育之，亭之毒之，养之覆之。"},
  {"id":"snt_ch_work_ddk_51_3","chapterId":"ch_work_ddk_51","textTraditional":"生而不有，為而不恃，長而不宰，是謂玄德。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"sinh nhi bất hữu， vi nhi bất thị， trưởng nhi bất tể， thị vị huyền đức。","pinyinReading":"shēng ér bù yǒu， wéi ér bù shì， zhǎng ér bù zǎi， shì wèi xuán dé。","translation":"Sinh mà không chiếm hữu, làm mà không cậy nhờ, nuôi lớn mà không cai quản — đó gọi là Huyền Đức.","textSimplified":"生而不有，为而不恃，长而不宰，是谓玄德。"},

  {"id":"snt_ch_work_ddk_52_1","chapterId":"ch_work_ddk_52","textTraditional":"天下有始，以為天下母。既得其母，以知其子；既知其子，復守其母，沒身不殆。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thiên hạ hữu thủy， dĩ vi thiên hạ mẫu。 ký đắc kỳ mẫu， dĩ tri kỳ tử； ký tri kỳ tử， phục thủ kỳ mẫu， một thân bất đãi。","pinyinReading":"tiān xià yǒu shǐ， yǐ wéi tiān xià mǔ。 jì dé qí mǔ， yǐ zhī qí zǐ； jì zhī qí zǐ， fù shǒu qí mǔ， mò shēn bù dài。","translation":"Thiên hạ có khởi đầu, lấy đó làm mẹ thiên hạ. Đã biết mẹ thì biết con; đã biết con, lại giữ lấy mẹ, suốt đời không nguy.","textSimplified":"天下有始，以为天下母。既得其母，以知其子；既知其子，复守其母，没身不殆。"},
  {"id":"snt_ch_work_ddk_52_2","chapterId":"ch_work_ddk_52","textTraditional":"塞其兌，閉其門，終身不勤。開其兌，濟其事，終身不救。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"tắc kỳ đoài， bế kỳ môn， chung thân bất cần。 khai kỳ đoài， tế kỳ sự， chung thân bất cứu。","pinyinReading":"sāi qí duì， bì qí mén， zhōng shēn bù qín。 kāi qí duì， jì qí shì， zhōng shēn bù jiù。","translation":"Bịt lỗ hổng, đóng cửa, suốt đời không vất vả. Mở lỗ hổng, xen vào việc, suốt đời không cứu nổi.","textSimplified":"塞其兑，闭其门，终身不勤。开其兑，济其事，终身不救。"},
  {"id":"snt_ch_work_ddk_52_3","chapterId":"ch_work_ddk_52","textTraditional":"見小曰明，守柔曰強。用其光，復歸其明，無遺身殃，是為習常。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"kiến tiểu viết minh， thủ nhu viết cường。 dụng kỳ quang， phục quy kỳ minh， vô di thân ương， thị vi tập thường。","pinyinReading":"jiàn xiǎo yuē míng， shǒu róu yuē qiáng。 yòng qí guāng， fù guī qí míng， wú yí shēn yāng， shì wéi xí cháng。","translation":"Thấy cái nhỏ gọi là sáng, giữ mềm mại gọi là mạnh. Dùng ánh sáng rồi quay về sự sáng suốt, không để lại họa cho thân — đó là tập quen với lẽ thường.","textSimplified":"见小曰明，守柔曰强。用其光，复归其明，无遗身殃，是为习常。"},

  {"id":"snt_ch_work_ddk_53_1","chapterId":"ch_work_ddk_53","textTraditional":"使我介然有知，行於大道，唯施是畏。大道甚夷，而人好徑。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"sử ngã giới nhiên hữu tri， hành ư đại đạo， duy thi thị úy。 đại đạo thậm di， nhi nhân hiếu kính。","pinyinReading":"shǐ wǒ jiè rán yǒu zhī， xíng yú dà dào， wéi shī shì wèi。 dà dào shèn yí， ér rén hào jìng。","translation":"Nếu ta có chút hiểu biết, đi trên Đại Đạo, chỉ sợ đi sai đường. Đại Đạo rất bằng phẳng, nhưng người ta thích đi đường tắt.","textSimplified":"使我介然有知，行于大道，唯施是畏。大道甚夷，而人好径。"},
  {"id":"snt_ch_work_ddk_53_2","chapterId":"ch_work_ddk_53","textTraditional":"朝甚除，田甚蕪，倉甚虛；服文綵，帶利劍，厭飲食，財貨有餘，是謂盜誇。非道也哉！","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"triều thậm trừ， điền thậm vu， thương thậm hư； phục văn thải， đái lợi kiếm， yếm ẩm thực， tài hóa hữu dư， thị vị đạo khoa。 phi đạo dã tai！","pinyinReading":"cháo shèn chú， tián shèn wú， cāng shèn xū； fú wén cǎi， dài lì jiàn， yàn yǐn shí， cái huò yǒu yú， shì wèi dào kuā。 fēi dào yě zāi！","translation":"Triều đình rất sạch đẹp, ruộng đồng rất hoang vu, kho lẫm rất trống; mặc áo thêu hoa, đeo gươm bén, chán ăn uống, của cải dư thừa — đó gọi là trộm khoe. Thật không phải Đạo!","textSimplified":"朝甚除，田甚芜，仓甚虚；服文彩，带利剑，厌饮食，财货有余，是谓盗夸。非道也哉！"},

  {"id":"snt_ch_work_ddk_54_1","chapterId":"ch_work_ddk_54","textTraditional":"善建者不拔，善抱者不脫，子孫以祭祀不輟。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thiện kiến giả bất bạt， thiện bão giả bất thoát， tử tôn dĩ tế tự bất chuyết。","pinyinReading":"shàn jiàn zhě bù bá， shàn bào zhě bù tuō， zǐ sūn yǐ jì sì bù chuò。","translation":"Xây dựng giỏi thì không bị nhổ, ôm giữ giỏi thì không bị tuột, con cháu nhờ đó mà tế tự không dứt.","textSimplified":"善建者不拔，善抱者不脱，子孙以祭祀不辍。"},
  {"id":"snt_ch_work_ddk_54_2","chapterId":"ch_work_ddk_54","textTraditional":"修之於身，其德乃真；修之於家，其德乃餘；修之於鄉，其德乃長；修之於邦，其德乃豐；修之於天下，其德乃普。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"tu chi ư thân， kỳ đức nãi chân； tu chi ư gia， kỳ đức nãi dư； tu chi ư hương， kỳ đức nãi trường； tu chi ư bang， kỳ đức nãi phong； tu chi ư thiên hạ， kỳ đức nãi phổ。","pinyinReading":"xiū zhī yú shēn， qí dé nǎi zhēn； xiū zhī yú jiā， qí dé nǎi yú； xiū zhī yú xiāng， qí dé nǎi cháng； xiū zhī yú bāng， qí dé nǎi fēng； xiū zhī yú tiān xià， qí dé nǎi pǔ。","translation":"Tu ở thân thì đức trở nên chân thật; tu ở nhà thì đức có thừa; tu ở làng thì đức lâu dài; tu ở nước thì đức dồi dào; tu ở thiên hạ thì đức khắp nơi.","textSimplified":"修之于身，其德乃真；修之于家，其德乃余；修之于乡，其德乃长；修之于邦，其德乃丰；修之于天下，其德乃普。"},
  {"id":"snt_ch_work_ddk_54_3","chapterId":"ch_work_ddk_54","textTraditional":"故以身觀身，以家觀家，以鄉觀鄉，以邦觀邦，以天下觀天下。吾何以知天下然哉？以此。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"cố dĩ thân quan thân， dĩ gia quan gia， dĩ hương quan hương， dĩ bang quan bang， dĩ thiên hạ quan thiên hạ。 ngô hà dĩ tri thiên hạ nhiên tai？ dĩ thử。","pinyinReading":"gù yǐ shēn guān shēn， yǐ jiā guān jiā， yǐ xiāng guān xiāng， yǐ bāng guān bāng， yǐ tiān xià guān tiān xià。 wú hé yǐ zhī tiān xià rán zāi？ yǐ cǐ。","translation":"Cho nên lấy thân xem thân, lấy nhà xem nhà, lấy làng xem làng, lấy nước xem nước, lấy thiên hạ xem thiên hạ. Ta làm sao biết thiên hạ ra sao? Nhờ vào đây.","textSimplified":"故以身观身，以家观家，以乡观乡，以邦观邦，以天下观天下。吾何以知天下然哉？以此。"},

  {"id":"snt_ch_work_ddk_55_1","chapterId":"ch_work_ddk_55","textTraditional":"含德之厚，比於赤子。毒蟲不螫，猛獸不據，攫鳥不搏。骨弱筋柔而握固。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"hàm đức chi hậu， tỷ ư xích tử。 độc trùng bất thích， mãnh thú bất cứ， quắc điểu bất bác。 cốt nhược cân nhu nhi ác cố。","pinyinReading":"hán dé zhī hòu， bǐ yú chì zǐ。 dú chóng bù shì， měng shòu bù jù， jué niǎo bù bó。 gǔ ruò jīn róu ér wò gù。","translation":"Người chứa đức dày, ví như trẻ sơ sinh. Sâu độc không cắn, thú dữ không vồ, chim ưng không quắp. Xương yếu gân mềm mà nắm chắc.","textSimplified":"含德之厚，比于赤子。毒虫不螫，猛兽不据，攫鸟不搏。骨弱筋柔而握固。"},
  {"id":"snt_ch_work_ddk_55_2","chapterId":"ch_work_ddk_55","textTraditional":"未知牝牡之合而朘作，精之至也。終日號而不嗄，和之至也。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"vị tri tẫn mẫu chi hợp nhi tuy tác， tinh chi chí dã。 chung nhật hào nhi bất á， hòa chi chí dã。","pinyinReading":"wèi zhī pìn mǔ zhī hé ér zuī zuò， jīng zhī zhì yě。 zhōng rì háo ér bù á， hé zhī zhì yě。","translation":"Chưa biết sự giao hợp mà cơ thể phản ứng, ấy là tinh khí đến cùng cực. Suốt ngày khóc mà không khản tiếng, ấy là sự hòa điệu đến cùng cực."},
  {"id":"snt_ch_work_ddk_55_3","chapterId":"ch_work_ddk_55","textTraditional":"知和曰常，知常曰明，益生曰祥，心使氣曰強。物壯則老，謂之不道，不道早已。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"tri hòa viết thường， tri thường viết minh， ích sinh viết tường， tâm sử khí viết cường。 vật tráng tắc lão， vị chi bất đạo， bất đạo tảo dĩ。","pinyinReading":"zhī hé yuē cháng， zhī cháng yuē míng， yì shēng yuē xiáng， xīn shǐ qì yuē qiáng。 wù zhuàng zé lǎo， wèi zhī bù dào， bù dào zǎo yǐ。","translation":"Biết hòa gọi là thường, biết thường gọi là sáng, tham sống gọi là điềm lành giả, lòng sai khiến khí gọi là cưỡng. Vật mạnh rồi già, gọi là trái Đạo, trái Đạo thì sớm tàn.","textSimplified":"知和曰常，知常曰明，益生曰祥，心使气曰强。物壮则老，谓之不道，不道早已。"},

  {"id":"snt_ch_work_ddk_56_1","chapterId":"ch_work_ddk_56","textTraditional":"知者不言，言者不知。塞其兌，閉其門，挫其銳，解其紛，和其光，同其塵，是謂玄同。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"tri giả bất ngôn， ngôn giả bất tri。 tắc kỳ đoài， bế kỳ môn， tỏa kỳ duệ， giải kỳ phân， hòa kỳ quang， đồng kỳ trần， thị vị huyền đồng。","pinyinReading":"zhī zhě bù yán， yán zhě bù zhī。 sāi qí duì， bì qí mén， cuò qí ruì， jiě qí fēn， hé qí guāng， tóng qí chén， shì wèi xuán tóng。","translation":"Người biết thì không nói, người nói thì không biết. Bịt lỗ hổng, đóng cửa, bẻ bớt sắc bén, gỡ rối rắm, hòa ánh sáng, hợp bụi trần — đó gọi là Huyền Đồng.","textSimplified":"知者不言，言者不知。塞其兑，闭其门，挫其锐，解其纷，和其光，同其尘，是谓玄同。"},
  {"id":"snt_ch_work_ddk_56_2","chapterId":"ch_work_ddk_56","textTraditional":"故不可得而親，不可得而疏；不可得而利，不可得而害；不可得而貴，不可得而賤。故為天下貴。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"cố bất khả đắc nhi thân， bất khả đắc nhi sơ； bất khả đắc nhi lợi， bất khả đắc nhi hại； bất khả đắc nhi quý， bất khả đắc nhi tiện。 cố vi thiên hạ quý。","pinyinReading":"gù bù kě dé ér qīn， bù kě dé ér shū； bù kě dé ér lì， bù kě dé ér hài； bù kě dé ér guì， bù kě dé ér jiàn。 gù wéi tiān xià guì。","translation":"Cho nên không thể thân gần, không thể xa cách; không thể làm lợi, không thể làm hại; không thể tôn quý, không thể khinh thường. Cho nên được thiên hạ quý trọng.","textSimplified":"故不可得而亲，不可得而疏；不可得而利，不可得而害；不可得而贵，不可得而贱。故为天下贵。"},

  {"id":"snt_ch_work_ddk_57_1","chapterId":"ch_work_ddk_57","textTraditional":"以正治國，以奇用兵，以無事取天下。吾何以知其然哉？以此。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"dĩ chính trị quốc， dĩ kỳ dụng binh， dĩ vô sự thủ thiên hạ。 ngô hà dĩ tri kỳ nhiên tai？ dĩ thử。","pinyinReading":"yǐ zhèng zhì guó， yǐ qí yòng bīng， yǐ wú shì qǔ tiān xià。 wú hé yǐ zhī qí rán zāi？ yǐ cǐ。","translation":"Lấy chính trực trị nước, lấy mưu lạ dùng binh, lấy vô sự mà lấy thiên hạ. Ta làm sao biết vậy? Nhờ vào đây.","textSimplified":"以正治国，以奇用兵，以无事取天下。吾何以知其然哉？以此。"},
  {"id":"snt_ch_work_ddk_57_2","chapterId":"ch_work_ddk_57","textTraditional":"天下多忌諱，而民彌貧；人多利器，國家滋昏；人多伎巧，奇物滋起；法令滋彰，盜賊多有。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"thiên hạ đa kị húy， nhi dân di bần； nhân đa lợi khí， quốc gia tư hôn； nhân đa kỹ xảo， kỳ vật tư khởi； pháp lệnh tư chương， đạo tặc đa hữu。","pinyinReading":"tiān xià duō jì huì， ér mín mí pín； rén duō lì qì， guó jiā zī hūn； rén duō jì qiǎo， qí wù zī qǐ； fǎ lìng zī zhāng， dào zéi duō yǒu。","translation":"Thiên hạ nhiều cấm kỵ thì dân càng nghèo; dân nhiều lợi khí thì nước càng rối; người nhiều xảo thuật thì vật lạ càng nổi; pháp lệnh càng rõ thì trộm cướp càng nhiều.","textSimplified":"天下多忌讳，而民弥贫；人多利器，国家滋昏；人多伎巧，奇物滋起；法令滋彰，盗贼多有。"},
  {"id":"snt_ch_work_ddk_57_3","chapterId":"ch_work_ddk_57","textTraditional":"故聖人云：我無為而民自化，我好靜而民自正，我無事而民自富，我無欲而民自樸。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"cố thánh nhân vân： ngã vô vi nhi dân tự hóa， ngã hiếu tĩnh nhi dân tự chính， ngã vô sự nhi dân tự phú， ngã vô dục nhi dân tự phác。","pinyinReading":"gù shèng rén yún： wǒ wú wéi ér mín zì huà， wǒ hào jìng ér mín zì zhèng， wǒ wú shì ér mín zì fù， wǒ wú yù ér mín zì pǔ。","translation":"Cho nên thánh nhân nói: Ta vô vi thì dân tự giáo hóa, ta ưa tĩnh lặng thì dân tự ngay thẳng, ta vô sự thì dân tự giàu có, ta không ham muốn thì dân tự chất phác.","textSimplified":"故圣人云：我无为而民自化，我好静而民自正，我无事而民自富，我无欲而民自朴。"},

  {"id":"snt_ch_work_ddk_58_1","chapterId":"ch_work_ddk_58","textTraditional":"其政悶悶，其民淳淳；其政察察，其民缺缺。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"kỳ chính muộn muộn， kỳ dân thuần thuần； kỳ chính sát sát， kỳ dân khuyết khuyết。","pinyinReading":"qí zhèng mèn mèn， qí mín chún chún； qí zhèng chá chá， qí mín quē quē。","translation":"Chính trị mơ hồ thì dân thuần hậu; chính trị xoi mói thì dân thiếu thốn.","textSimplified":"其政闷闷，其民淳淳；其政察察，其民缺缺。"},
  {"id":"snt_ch_work_ddk_58_2","chapterId":"ch_work_ddk_58","textTraditional":"禍兮福之所倚，福兮禍之所伏。孰知其極？其無正也。正復為奇，善復為妖。人之迷，其日固久。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"họa hề phúc chi sở ỷ， phúc hề họa chi sở phục。 thục tri kỳ cực？ kỳ vô chính dã。 chính phục vi kỳ， thiện phục vi yêu。 nhân chi mê， kỳ nhật cố cửu。","pinyinReading":"huò xī fú zhī suǒ yǐ， fú xī huò zhī suǒ fú。 shú zhī qí jí？ qí wú zhèng yě。 zhèng fù wéi qí， shàn fù wéi yāo。 rén zhī mí， qí rì gù jiǔ。","translation":"Họa là chỗ phúc nương tựa, phúc là chỗ họa ẩn nấp. Ai biết đâu là cùng cực? Không có cái chính cố định. Chính lại thành lệch, thiện lại thành xấu. Sự mê hoặc của người đã lâu lắm rồi.","textSimplified":"祸兮福之所倚，福兮祸之所伏。孰知其极？其无正也。正复为奇，善复为妖。人之迷，其日固久。"},
  {"id":"snt_ch_work_ddk_58_3","chapterId":"ch_work_ddk_58","textTraditional":"是以聖人方而不割，廉而不劌，直而不肆，光而不耀。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"thị dĩ thánh nhân phương nhi bất cát， liêm nhi bất quệ， trực nhi bất tứ， quang nhi bất diệu。","pinyinReading":"shì yǐ shèng rén fāng ér bù gē， lián ér bù guì， zhí ér bù sì， guāng ér bù yào。","translation":"Vì thế thánh nhân vuông mà không cắt, liêm khiết mà không làm đau, thẳng mà không phóng túng, sáng mà không chói.","textSimplified":"是以圣人方而不割，廉而不刿，直而不肆，光而不耀。"},

  {"id":"snt_ch_work_ddk_59_1","chapterId":"ch_work_ddk_59","textTraditional":"治人事天，莫若嗇。夫唯嗇，是謂早服；早服謂之重積德。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"trị nhân sự thiên， mạc nhược sắc。 phù duy sắc， thị vị tảo phục； tảo phục vị chi trọng tích đức。","pinyinReading":"zhì rén shì tiān， mò ruò sè。 fú wéi sè， shì wèi zǎo fú； zǎo fú wèi zhī chóng jī dé。","translation":"Trị người thờ trời, không gì bằng tiết kiệm. Chỉ có tiết kiệm mới là sớm thuận theo; sớm thuận theo nghĩa là tích đức dày.","textSimplified":"治人事天，莫若啬。夫唯啬，是谓早服；早服谓之重积德。"},
  {"id":"snt_ch_work_ddk_59_2","chapterId":"ch_work_ddk_59","textTraditional":"重積德則無不克，無不克則莫知其極，莫知其極可以有國。有國之母，可以長久，是謂深根固柢，長生久視之道。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"trọng tích đức tắc vô bất khắc， vô bất khắc tắc mạc tri kỳ cực， mạc tri kỳ cực khả dĩ hữu quốc。 hữu quốc chi mẫu， khả dĩ trường cửu， thị vị thâm căn cố đế， trường sinh cửu thị chi đạo。","pinyinReading":"chóng jī dé zé wú bù kè， wú bù kè zé mò zhī qí jí， mò zhī qí jí kě yǐ yǒu guó。 yǒu guó zhī mǔ， kě yǐ cháng jiǔ， shì wèi shēn gēn gù dǐ， cháng shēng jiǔ shì zhī dào。","translation":"Tích đức dày thì không gì không thắng, không gì không thắng thì không ai biết giới hạn, không ai biết giới hạn thì có thể nắm giữ đất nước. Nắm được gốc rễ của nước thì có thể lâu dài — đó gọi là gốc sâu rễ bền, đạo trường sinh bất diệt.","textSimplified":"重积德则无不克，无不克则莫知其极，莫知其极可以有国。有国之母，可以长久，是谓深根固柢，长生久视之道。"},

  {"id":"snt_ch_work_ddk_60_1","chapterId":"ch_work_ddk_60","textTraditional":"治大國，若烹小鮮。以道蒞天下，其鬼不神。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"trị đại quốc， nhược phanh tiểu tiên。 dĩ đạo lị thiên hạ， kỳ quỷ bất thần。","pinyinReading":"zhì dà guó， ruò pēng xiǎo xiān。 yǐ dào lì tiān xià， qí guǐ bù shén。","translation":"Trị nước lớn như nấu cá nhỏ. Lấy Đạo mà cai quản thiên hạ thì ma quỷ không linh.","textSimplified":"治大国，若烹小鲜。以道莅天下，其鬼不神。"},
  {"id":"snt_ch_work_ddk_60_2","chapterId":"ch_work_ddk_60","textTraditional":"非其鬼不神，其神不傷人；非其神不傷人，聖人亦不傷人。夫兩不相傷，故德交歸焉。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"phi kỳ quỷ bất thần， kỳ thần bất thương nhân； phi kỳ thần bất thương nhân， thánh nhân diệc bất thương nhân。 phù lưỡng bất tương thương， cố đức giao quy yên。","pinyinReading":"fēi qí guǐ bù shén， qí shén bù shāng rén； fēi qí shén bù shāng rén， shèng rén yì bù shāng rén。 fú liǎng bù xiāng shāng， gù dé jiāo guī yān。","translation":"Không phải quỷ không linh, mà thần không hại người; không phải thần không hại người, mà thánh nhân cũng không hại người. Hai bên không hại nhau, nên đức giao hòa quy về.","textSimplified":"非其鬼不神，其神不伤人；非其神不伤人，圣人亦不伤人。夫两不相伤，故德交归焉。"},

  {"id":"snt_ch_work_ddk_61_1","chapterId":"ch_work_ddk_61","textTraditional":"大邦者下流，天下之牝，天下之交也。牝常以靜勝牡，以靜為下。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"đại bang giả hạ lưu， thiên hạ chi tẫn， thiên hạ chi giao dã。 tẫn thường dĩ tĩnh thắng mẫu， dĩ tĩnh vi hạ。","pinyinReading":"dà bāng zhě xià liú， tiān xià zhī pìn， tiān xià zhī jiāo yě。 pìn cháng yǐ jìng shèng mǔ， yǐ jìng wéi xià。","translation":"Nước lớn như dòng chảy xuống thấp, là giống cái của thiên hạ, là nơi giao hội của thiên hạ. Giống cái thường lấy tĩnh mà thắng giống đực, lấy tĩnh mà ở dưới.","textSimplified":"大邦者下流，天下之牝，天下之交也。牝常以静胜牡，以静为下。"},
  {"id":"snt_ch_work_ddk_61_2","chapterId":"ch_work_ddk_61","textTraditional":"故大邦以下小邦，則取小邦；小邦以下大邦，則取大邦。故或下以取，或下而取。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"cố đại bang dĩ hạ tiểu bang， tắc thủ tiểu bang； tiểu bang dĩ hạ đại bang， tắc thủ đại bang。 cố hoặc hạ dĩ thủ， hoặc hạ nhi thủ。","pinyinReading":"gù dà bāng yǐ xià xiǎo bāng， zé qǔ xiǎo bāng； xiǎo bāng yǐ xià dà bāng， zé qǔ dà bāng。 gù huò xià yǐ qǔ， huò xià ér qǔ。","translation":"Cho nên nước lớn hạ mình với nước nhỏ thì thu phục được nước nhỏ; nước nhỏ hạ mình với nước lớn thì được nước lớn thu nhận. Cho nên hoặc hạ mình để thu phục, hoặc hạ mình mà được thu nhận."},
  {"id":"snt_ch_work_ddk_61_3","chapterId":"ch_work_ddk_61","textTraditional":"大邦不過欲兼畜人，小邦不過欲入事人。夫兩者各得所欲，大者宜為下。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"đại bang bất quá dục kiêm húc nhân， tiểu bang bất quá dục nhập sự nhân。 phù lưỡng giả các đắc sở dục， đại giả nghi vi hạ。","pinyinReading":"dà bāng bù guò yù jiān xù rén， xiǎo bāng bù guò yù rù shì rén。 fú liǎng zhě gè dé suǒ yù， dà zhě yí wéi xià。","translation":"Nước lớn chẳng qua muốn gồm nuôi người, nước nhỏ chẳng qua muốn vào phục vụ người. Hai bên đều được điều mong muốn, bên lớn nên ở dưới."},

  {"id":"snt_ch_work_ddk_62_1","chapterId":"ch_work_ddk_62","textTraditional":"道者萬物之奧。善人之寶，不善人之所保。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"đạo giả vạn vật chi áo。 thiện nhân chi bảo， bất thiện nhân chi sở bảo。","pinyinReading":"dào zhě wàn wù zhī ào。 shàn rén zhī bǎo， bù shàn rén zhī suǒ bǎo。","translation":"Đạo là chỗ sâu kín của muôn vật. Là báu vật của người thiện, là chỗ nương của người bất thiện.","textSimplified":"道者万物之奥。善人之宝，不善人之所保。"},
  {"id":"snt_ch_work_ddk_62_2","chapterId":"ch_work_ddk_62","textTraditional":"美言可以市尊，美行可以加人。人之不善，何棄之有？","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"mỹ ngôn khả dĩ thị tôn， mỹ hành khả dĩ gia nhân。 nhân chi bất thiện， hà khí chi hữu？","pinyinReading":"měi yán kě yǐ shì zūn， měi xíng kě yǐ jiā rén。 rén zhī bù shàn， hé qì zhī yǒu？","translation":"Lời hay có thể mua được sự tôn trọng, hành vi đẹp có thể vượt lên người khác. Người bất thiện, sao lại bỏ họ?"},
  {"id":"snt_ch_work_ddk_62_3","chapterId":"ch_work_ddk_62","textTraditional":"故立天子，置三公，雖有拱璧以先駟馬，不如坐進此道。古之所以貴此道者何？不曰以求得，有罪以免邪？故為天下貴。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"cố lập thiên tử， trí tam công， tuy hữu cung bích dĩ tiên tứ mã， bất như tọa tiến thử đạo。 cổ chi sở dĩ quý thử đạo giả hà？ bất viết dĩ cầu đắc， hữu tội dĩ miễn tà？ cố vi thiên hạ quý。","pinyinReading":"gù lì tiān zǐ， zhì sān gōng， suī yǒu gǒng bì yǐ xiān sì mǎ， bù rú zuò jìn cǐ dào。 gǔ zhī suǒ yǐ guì cǐ dào zhě hé？ bù yuē yǐ qiú dé， yǒu zuì yǐ miǎn yé？ gù wéi tiān xià guì。","translation":"Cho nên lập thiên tử, đặt ba công, tuy có ngọc bích lớn dâng trước bốn ngựa, không bằng ngồi mà tiến cử Đạo này. Xưa sở dĩ quý Đạo này vì sao? Chẳng phải nhờ nó mà cầu được, có tội thì được miễn sao? Cho nên là quý nhất thiên hạ.","textSimplified":"故立天子，置三公，虽有拱璧以先驷马，不如坐进此道。古之所以贵此道者何？不曰以求得，有罪以免邪？故为天下贵。"},

  {"id":"snt_ch_work_ddk_63_1","chapterId":"ch_work_ddk_63","textTraditional":"為無為，事無事，味無味。大小多少，報怨以德。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"vi vô vi， sự vô sự， vị vô vị。 đại tiểu đa thiểu， báo oán dĩ đức。","pinyinReading":"wéi wú wéi， shì wú shì， wèi wú wèi。 dà xiǎo duō shǎo， bào yuàn yǐ dé。","translation":"Làm cái vô vi, làm việc vô sự, nếm cái vô vị. Lớn nhỏ nhiều ít, lấy đức báo oán.","textSimplified":"为无为，事无事，味无味。大小多少，报怨以德。"},
  {"id":"snt_ch_work_ddk_63_2","chapterId":"ch_work_ddk_63","textTraditional":"圖難於其易，為大於其細。天下難事必作於易，天下大事必作於細。是以聖人終不為大，故能成其大。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"đồ nan ư kỳ dị， vi đại ư kỳ tế。 thiên hạ nan sự tất tác ư dị， thiên hạ đại sự tất tác ư tế。 thị dĩ thánh nhân chung bất vi đại， cố năng thành kỳ đại。","pinyinReading":"tú nán yú qí yì， wéi dà yú qí xì。 tiān xià nán shì bì zuò yú yì， tiān xià dà shì bì zuò yú xì。 shì yǐ shèng rén zhōng bù wéi dà， gù néng chéng qí dà。","translation":"Lo việc khó ở chỗ dễ, làm việc lớn ở chỗ nhỏ. Việc khó thiên hạ tất bắt đầu từ dễ, việc lớn thiên hạ tất bắt đầu từ nhỏ. Vì thế thánh nhân không bao giờ tự cho mình lớn, nên mới thành được cái lớn.","textSimplified":"图难于其易，为大于其细。天下难事必作于易，天下大事必作于细。是以圣人终不为大，故能成其大。"},
  {"id":"snt_ch_work_ddk_63_3","chapterId":"ch_work_ddk_63","textTraditional":"夫輕諾必寡信，多易必多難。是以聖人猶難之，故終無難矣。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"phù khinh nặc tất quả tín， đa dị tất đa nan。 thị dĩ thánh nhân do nan chi， cố chung vô nan hĩ。","pinyinReading":"fú qīng nuò bì guǎ xìn， duō yì bì duō nán。 shì yǐ shèng rén yóu nán zhī， gù zhōng wú nán yǐ。","translation":"Hứa dễ dàng tất ít giữ lời, coi dễ nhiều tất gặp khó nhiều. Vì thế thánh nhân coi mọi việc đều khó, nên cuối cùng không có gì khó.","textSimplified":"夫轻诺必寡信，多易必多难。是以圣人犹难之，故终无难矣。"},

  {"id":"snt_ch_work_ddk_64_1","chapterId":"ch_work_ddk_64","textTraditional":"其安易持，其未兆易謀，其脆易泮，其微易散。為之於未有，治之於未亂。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"kỳ an dị trì， kỳ vị triệu dị mưu， kỳ thúy dị phán， kỳ vi dị tán。 vi chi ư vị hữu， trị chi ư vị loạn。","pinyinReading":"qí ān yì chí， qí wèi zhào yì móu， qí cuì yì pàn， qí wēi yì sàn。 wéi zhī yú wèi yǒu， zhì zhī yú wèi luàn。","translation":"Lúc yên thì dễ giữ, chưa có dấu hiệu thì dễ tính, lúc giòn thì dễ vỡ, lúc nhỏ thì dễ tan. Làm từ khi chưa có, trị từ khi chưa loạn.","textSimplified":"其安易持，其未兆易谋，其脆易泮，其微易散。为之于未有，治之于未乱。"},
  {"id":"snt_ch_work_ddk_64_2","chapterId":"ch_work_ddk_64","textTraditional":"合抱之木，生於毫末；九層之臺，起於累土；千里之行，始於足下。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"hợp bão chi mộc， sinh ư hào mạt； cửu tằng chi đài， khởi ư lũy thổ； thiên lý chi hành， thủy ư túc hạ。","pinyinReading":"hé bào zhī mù， shēng yú háo mò； jiǔ céng zhī tái， qǐ yú lěi tǔ； qiān lǐ zhī xíng， shǐ yú zú xià。","translation":"Cây ôm một vòng, mọc từ mầm nhỏ; đài chín tầng, dựng từ nắm đất; đường ngàn dặm, bắt đầu từ bước chân.","textSimplified":"合抱之木，生于毫末；九层之台，起于累土；千里之行，始于足下。"},
  {"id":"snt_ch_work_ddk_64_3","chapterId":"ch_work_ddk_64","textTraditional":"為者敗之，執者失之。是以聖人無為故無敗，無執故無失。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"vi giả bại chi， chấp giả thất chi。 thị dĩ thánh nhân vô vi cố vô bại， vô chấp cố vô thất。","pinyinReading":"wéi zhě bài zhī， zhí zhě shī zhī。 shì yǐ shèng rén wú wéi gù wú bài， wú zhí gù wú shī。","translation":"Cưỡng làm thì hỏng, nắm giữ thì mất. Vì thế thánh nhân vô vi nên không hỏng, không nắm giữ nên không mất.","textSimplified":"为者败之，执者失之。是以圣人无为故无败，无执故无失。"},
  {"id":"snt_ch_work_ddk_64_4","chapterId":"ch_work_ddk_64","textTraditional":"民之從事，常於幾成而敗之。慎終如始，則無敗事。是以聖人欲不欲，不貴難得之貨；學不學，復衆人之所過，以輔萬物之自然而不敢為。","sentenceOrder":4,"paragraphGroup":3,"hanVietReading":"dân chi tòng sự， thường ư cơ thành nhi bại chi。 thận chung như thủy， tắc vô bại sự。 thị dĩ thánh nhân dục bất dục， bất quý nan đắc chi hóa； học bất học， phục chúng nhân chi sở quá， dĩ phụ vạn vật chi tự nhiên nhi bất cảm vi。","pinyinReading":"mín zhī cóng shì， cháng yú jī chéng ér bài zhī。 shèn zhōng rú shǐ， zé wú bài shì。 shì yǐ shèng rén yù bù yù， bù guì nán dé zhī huò； xué bù xué， fù zhòng rén zhī suǒ guò， yǐ fǔ wàn wù zhī zì rán ér bù gǎn wéi。","translation":"Dân làm việc thường sắp thành lại hỏng. Cẩn thận lúc cuối như lúc đầu thì không có việc hỏng. Vì thế thánh nhân muốn cái không muốn, không quý của khó được; học cái không học, bù lại chỗ mọi người đã lầm, để giúp muôn vật tự nhiên mà không dám cưỡng làm.","textSimplified":"民之从事，常于几成而败之。慎终如始，则无败事。是以圣人欲不欲，不贵难得之货；学不学，复众人之所过，以辅万物之自然而不敢为。"},

  {"id":"snt_ch_work_ddk_65_1","chapterId":"ch_work_ddk_65","textTraditional":"古之善為道者，非以明民，將以愚之。民之難治，以其智多。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"cổ chi thiện vi đạo giả， phi dĩ minh dân， tương dĩ ngu chi。 dân chi nan trị， dĩ kỳ trí đa。","pinyinReading":"gǔ zhī shàn wéi dào zhě， fēi yǐ míng mín， jiāng yǐ yú zhī。 mín zhī nán zhì， yǐ qí zhì duō。","translation":"Bậc xưa giỏi hành Đạo, không phải làm dân sáng, mà làm dân mộc mạc. Dân khó trị vì trí xảo quá nhiều.","textSimplified":"古之善为道者，非以明民，将以愚之。民之难治，以其智多。"},
  {"id":"snt_ch_work_ddk_65_2","chapterId":"ch_work_ddk_65","textTraditional":"故以智治國，國之賊；不以智治國，國之福。知此兩者亦稽式。常知稽式，是謂玄德。玄德深矣遠矣，與物反矣，然後乃至大順。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"cố dĩ trí trị quốc， quốc chi tặc； bất dĩ trí trị quốc， quốc chi phúc。 tri thử lưỡng giả diệc kê thức。 thường tri kê thức， thị vị huyền đức。 huyền đức thâm hĩ viễn hĩ， dữ vật phản hĩ， nhiên hậu nãi chí đại thuận。","pinyinReading":"gù yǐ zhì zhì guó， guó zhī zéi； bù yǐ zhì zhì guó， guó zhī fú。 zhī cǐ liǎng zhě yì jī shì。 cháng zhī jī shì， shì wèi xuán dé。 xuán dé shēn yǐ yuǎn yǐ， yǔ wù fǎn yǐ， rán hòu nǎi zhì dà shùn。","translation":"Cho nên dùng trí xảo trị nước là giặc của nước; không dùng trí xảo trị nước là phúc của nước. Biết hai điều này cũng là khuôn phép. Luôn biết khuôn phép, đó gọi là Huyền Đức. Huyền Đức sâu xa, ngược lại với vật, rồi sau mới đạt đến đại thuận.","textSimplified":"故以智治国，国之贼；不以智治国，国之福。知此两者亦稽式。常知稽式，是谓玄德。玄德深矣远矣，与物反矣，然后乃至大顺。"},

  {"id":"snt_ch_work_ddk_66_1","chapterId":"ch_work_ddk_66","textTraditional":"江海之所以能為百谷王者，以其善下之，故能為百谷王。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"giang hải chi sở dĩ năng vi bách cốc vương giả， dĩ kỳ thiện hạ chi， cố năng vi bách cốc vương。","pinyinReading":"jiāng hǎi zhī suǒ yǐ néng wéi bǎi gǔ wáng zhě， yǐ qí shàn xià zhī， gù néng wéi bǎi gǔ wáng。","translation":"Sông biển sở dĩ làm vua trăm suối là vì khéo ở dưới chúng, nên mới làm vua trăm suối."},
  {"id":"snt_ch_work_ddk_66_2","chapterId":"ch_work_ddk_66","textTraditional":"是以聖人欲上民，必以言下之；欲先民，必以身後之。是以聖人處上而民不重，處前而民不害。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thị dĩ thánh nhân dục thượng dân， tất dĩ ngôn hạ chi； dục tiên dân， tất dĩ thân hậu chi。 thị dĩ thánh nhân xử thượng nhi dân bất trọng， xử tiền nhi dân bất hại。","pinyinReading":"shì yǐ shèng rén yù shàng mín， bì yǐ yán xià zhī； yù xiān mín， bì yǐ shēn hòu zhī。 shì yǐ shèng rén chǔ shàng ér mín bù zhòng， chǔ qián ér mín bù hài。","translation":"Vì thế thánh nhân muốn ở trên dân, tất phải lấy lời hạ mình; muốn đi trước dân, tất phải lấy thân đặt sau. Vì thế thánh nhân ở trên mà dân không thấy nặng, ở trước mà dân không thấy hại.","textSimplified":"是以圣人欲上民，必以言下之；欲先民，必以身后之。是以圣人处上而民不重，处前而民不害。"},
  {"id":"snt_ch_work_ddk_66_3","chapterId":"ch_work_ddk_66","textTraditional":"是以天下樂推而不厭。以其不爭，故天下莫能與之爭。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"thị dĩ thiên hạ lạc thôi nhi bất yếm。 dĩ kỳ bất tranh， cố thiên hạ mạc năng dữ chi tranh。","pinyinReading":"shì yǐ tiān xià lè tuī ér bù yàn。 yǐ qí bù zhēng， gù tiān xià mò néng yǔ zhī zhēng。","translation":"Vì thế thiên hạ vui lòng tôn lên mà không chán. Vì không tranh, nên thiên hạ không ai tranh nổi.","textSimplified":"是以天下乐推而不厌。以其不争，故天下莫能与之争。"},

  {"id":"snt_ch_work_ddk_67_1","chapterId":"ch_work_ddk_67","textTraditional":"天下皆謂我道大，似不肖。夫唯大，故似不肖。若肖，久矣其細也夫。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thiên hạ giai vị ngã đạo đại， tự bất tiếu。 phù duy đại， cố tự bất tiếu。 nhược tiếu， cửu hĩ kỳ tế dã phù。","pinyinReading":"tiān xià jiē wèi wǒ dào dà， sì bù xiào。 fú wéi dà， gù sì bù xiào。 ruò xiào， jiǔ yǐ qí xì yě fú。","translation":"Thiên hạ đều nói Đạo ta lớn, dường như không giống gì cả. Chính vì lớn nên mới dường như không giống. Nếu giống thì đã nhỏ bé từ lâu rồi.","textSimplified":"天下皆谓我道大，似不肖。夫唯大，故似不肖。若肖，久矣其细也夫。"},
  {"id":"snt_ch_work_ddk_67_2","chapterId":"ch_work_ddk_67","textTraditional":"我有三寶，持而保之：一曰慈，二曰儉，三曰不敢為天下先。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"ngã hữu tam bảo， trì nhi bảo chi： nhất viết từ， nhị viết kiệm， tam viết bất cảm vi thiên hạ tiên。","pinyinReading":"wǒ yǒu sān bǎo， chí ér bǎo zhī： yī yuē cí， èr yuē jiǎn， sān yuē bù gǎn wéi tiān xià xiān。","translation":"Ta có ba báu vật, giữ gìn và bảo vệ: một là từ bi, hai là tiết kiệm, ba là không dám đứng trước thiên hạ.","textSimplified":"我有三宝，持而保之：一曰慈，二曰俭，三曰不敢为天下先。"},
  {"id":"snt_ch_work_ddk_67_3","chapterId":"ch_work_ddk_67","textTraditional":"慈故能勇，儉故能廣，不敢為天下先故能成器長。今舍慈且勇，舍儉且廣，舍後且先，死矣！","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"từ cố năng dũng， kiệm cố năng quảng， bất cảm vi thiên hạ tiên cố năng thành khí trưởng。 kim xả từ thả dũng， xả kiệm thả quảng， xả hậu thả tiên， tử hĩ！","pinyinReading":"cí gù néng yǒng， jiǎn gù néng guǎng， bù gǎn wéi tiān xià xiān gù néng chéng qì zhǎng。 jīn shě cí qiě yǒng， shě jiǎn qiě guǎng， shě hòu qiě xiān， sǐ yǐ！","translation":"Từ bi nên mới dũng cảm, tiết kiệm nên mới rộng rãi, không dám đi trước thiên hạ nên mới thành bậc đứng đầu. Nay bỏ từ bi mà muốn dũng, bỏ tiết kiệm mà muốn rộng, bỏ sau mà muốn trước — chết thôi!","textSimplified":"慈故能勇，俭故能广，不敢为天下先故能成器长。今舍慈且勇，舍俭且广，舍后且先，死矣！"},
  {"id":"snt_ch_work_ddk_67_4","chapterId":"ch_work_ddk_67","textTraditional":"夫慈，以戰則勝，以守則固。天將救之，以慈衛之。","sentenceOrder":4,"paragraphGroup":3,"hanVietReading":"phù từ， dĩ chiến tắc thắng， dĩ thủ tắc cố。 thiên tương cứu chi， dĩ từ vệ chi。","pinyinReading":"fú cí， yǐ zhàn zé shèng， yǐ shǒu zé gù。 tiān jiāng jiù zhī， yǐ cí wèi zhī。","translation":"Từ bi, dùng để chiến thì thắng, dùng để giữ thì vững. Trời muốn cứu ai, lấy từ bi mà bảo vệ.","textSimplified":"夫慈，以战则胜，以守则固。天将救之，以慈卫之。"},

  {"id":"snt_ch_work_ddk_68_1","chapterId":"ch_work_ddk_68","textTraditional":"善為士者不武，善戰者不怒，善勝敵者不與，善用人者為之下。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thiện vi sĩ giả bất vũ， thiện chiến giả bất nộ， thiện thắng địch giả bất dữ， thiện dụng nhân giả vi chi hạ。","pinyinReading":"shàn wéi shì zhě bù wǔ， shàn zhàn zhě bù nù， shàn shèng dí zhě bù yǔ， shàn yòng rén zhě wéi zhī xià。","translation":"Người giỏi làm tướng thì không hung bạo, giỏi chiến đấu thì không nóng giận, giỏi thắng địch thì không tranh đua, giỏi dùng người thì ở dưới người.","textSimplified":"善为士者不武，善战者不怒，善胜敌者不与，善用人者为之下。"},
  {"id":"snt_ch_work_ddk_68_2","chapterId":"ch_work_ddk_68","textTraditional":"是謂不爭之德，是謂用人之力，是謂配天古之極。","sentenceOrder":2,"paragraphGroup":1,"hanVietReading":"thị vị bất tranh chi đức， thị vị dụng nhân chi lực， thị vị phối thiên cổ chi cực。","pinyinReading":"shì wèi bù zhēng zhī dé， shì wèi yòng rén zhī lì， shì wèi pèi tiān gǔ zhī jí。","translation":"Đó gọi là đức không tranh, đó gọi là sức dùng người, đó gọi là sánh ngang với trời xưa ở cực điểm.","textSimplified":"是谓不争之德，是谓用人之力，是谓配天古之极。"},

  {"id":"snt_ch_work_ddk_69_1","chapterId":"ch_work_ddk_69","textTraditional":"用兵有言：吾不敢為主而為客，不敢進寸而退尺。是謂行無行，攘無臂，扔無敵，執無兵。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"dụng binh hữu ngôn： ngô bất cảm vi chủ nhi vi khách， bất cảm tiến thốn nhi thoái xích。 thị vị hành vô hành， nhương vô tý， nhưng vô địch， chấp vô binh。","pinyinReading":"yòng bīng yǒu yán： wú bù gǎn wéi zhǔ ér wéi kè， bù gǎn jìn cùn ér tuì chǐ。 shì wèi xíng wú xíng， rǎng wú bì， réng wú dí， zhí wú bīng。","translation":"Dùng binh có câu: Ta không dám làm chủ mà làm khách, không dám tiến một tấc mà lùi một thước. Đó gọi là đi mà không hàng ngũ, xắn tay mà không cánh tay, ném mà không có địch, nắm mà không có binh.","textSimplified":"用兵有言：吾不敢为主而为客，不敢进寸而退尺。是谓行无行，攘无臂，扔无敌，执无兵。"},
  {"id":"snt_ch_work_ddk_69_2","chapterId":"ch_work_ddk_69","textTraditional":"禍莫大於輕敵，輕敵幾喪吾寶。故抗兵相若，哀者勝矣。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"họa mạc đại ư khinh địch， khinh địch cơ táng ngô bảo。 cố kháng binh tương nhược， ai giả thắng hĩ。","pinyinReading":"huò mò dà yú qīng dí， qīng dí jī sàng wú bǎo。 gù kàng bīng xiāng ruò， āi zhě shèng yǐ。","translation":"Họa không gì lớn bằng coi nhẹ kẻ địch, coi nhẹ kẻ địch suýt mất báu vật của ta. Cho nên hai bên cân sức, bên bi thương sẽ thắng.","textSimplified":"祸莫大于轻敌，轻敌几丧吾宝。故抗兵相若，哀者胜矣。"},

  {"id":"snt_ch_work_ddk_70_1","chapterId":"ch_work_ddk_70","textTraditional":"吾言甚易知，甚易行。天下莫能知，莫能行。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"ngô ngôn thậm dị tri， thậm dị hành。 thiên hạ mạc năng tri， mạc năng hành。","pinyinReading":"wú yán shèn yì zhī， shèn yì xíng。 tiān xià mò néng zhī， mò néng xíng。","translation":"Lời ta rất dễ hiểu, rất dễ làm. Thiên hạ không ai hiểu được, không ai làm được."},
  {"id":"snt_ch_work_ddk_70_2","chapterId":"ch_work_ddk_70","textTraditional":"言有宗，事有君。夫唯無知，是以不我知。知我者希，則我者貴。是以聖人被褐而懷玉。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"ngôn hữu tông， sự hữu quân。 phù duy vô tri， thị dĩ bất ngã tri。 tri ngã giả hi， tắc ngã giả quý。 thị dĩ thánh nhân bị hạt nhi hoài ngọc。","pinyinReading":"yán yǒu zōng， shì yǒu jūn。 fú wéi wú zhī， shì yǐ bù wǒ zhī。 zhī wǒ zhě xī， zé wǒ zhě guì。 shì yǐ shèng rén bèi hè ér huái yù。","translation":"Lời có tông chỉ, việc có chủ đề. Vì người ta không biết điều đó, nên không hiểu ta. Hiểu ta thì ít, bắt chước ta thì quý. Vì thế thánh nhân mặc áo vải thô mà ôm ngọc trong lòng.","textSimplified":"言有宗，事有君。夫唯无知，是以不我知。知我者希，则我者贵。是以圣人被褐而怀玉。"},

  {"id":"snt_ch_work_ddk_71_1","chapterId":"ch_work_ddk_71","textTraditional":"知不知，尚矣；不知知，病也。聖人不病，以其病病。夫唯病病，是以不病。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"tri bất tri， thượng hĩ； bất tri tri， bệnh dã。 thánh nhân bất bệnh， dĩ kỳ bệnh bệnh。 phù duy bệnh bệnh， thị dĩ bất bệnh。","pinyinReading":"zhī bù zhī， shàng yǐ； bù zhī zhī， bìng yě。 shèng rén bù bìng， yǐ qí bìng bìng。 fú wéi bìng bìng， shì yǐ bù bìng。","translation":"Biết mà cho là không biết, đó là cao; không biết mà cho là biết, đó là bệnh. Thánh nhân không bệnh vì lấy bệnh làm bệnh. Chính vì coi bệnh là bệnh, nên không bệnh."},

  {"id":"snt_ch_work_ddk_72_1","chapterId":"ch_work_ddk_72","textTraditional":"民不畏威，則大威至。無狎其所居，無厭其所生。夫唯不厭，是以不厭。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"dân bất úy uy， tắc đại uy chí。 vô hiệp kỳ sở cư， vô yếm kỳ sở sinh。 phù duy bất yếm， thị dĩ bất yếm。","pinyinReading":"mín bù wèi wēi， zé dà wēi zhì。 wú xiá qí suǒ jū， wú yàn qí suǒ shēng。 fú wéi bù yàn， shì yǐ bù yàn。","translation":"Dân không sợ uy quyền thì đại uy sẽ đến. Đừng ép chật chỗ ở của dân, đừng bức bách cuộc sống của dân. Chính vì không bức bách nên dân không chán ghét.","textSimplified":"民不畏威，则大威至。无狎其所居，无厌其所生。夫唯不厌，是以不厌。"},
  {"id":"snt_ch_work_ddk_72_2","chapterId":"ch_work_ddk_72","textTraditional":"是以聖人自知不自見，自愛不自貴。故去彼取此。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thị dĩ thánh nhân tự tri bất tự kiến， tự ái bất tự quý。 cố khứ bỉ thủ thử。","pinyinReading":"shì yǐ shèng rén zì zhī bù zì xiàn， zì ài bù zì guì。 gù qù bǐ qǔ cǐ。","translation":"Vì thế thánh nhân tự biết mà không tự phô, tự yêu mà không tự tôn. Cho nên bỏ cái kia lấy cái này.","textSimplified":"是以圣人自知不自见，自爱不自贵。故去彼取此。"},

  {"id":"snt_ch_work_ddk_73_1","chapterId":"ch_work_ddk_73","textTraditional":"勇於敢則殺，勇於不敢則活。此兩者，或利或害。天之所惡，孰知其故？","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"dũng ư cảm tắc sát， dũng ư bất cảm tắc hoạt。 thử lưỡng giả， hoặc lợi hoặc hại。 thiên chi sở ố， thục tri kỳ cố？","pinyinReading":"yǒng yú gǎn zé shā， yǒng yú bù gǎn zé huó。 cǐ liǎng zhě， huò lì huò hài。 tiān zhī suǒ wù， shú zhī qí gù？","translation":"Dũng cảm dám làm thì chết, dũng cảm không dám làm thì sống. Hai điều này, hoặc lợi hoặc hại. Trời ghét điều gì, ai biết được nguyên nhân?","textSimplified":"勇于敢则杀，勇于不敢则活。此两者，或利或害。天之所恶，孰知其故？"},
  {"id":"snt_ch_work_ddk_73_2","chapterId":"ch_work_ddk_73","textTraditional":"天之道，不爭而善勝，不言而善應，不召而自來，繟然而善謀。天網恢恢，疏而不失。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thiên chi đạo， bất tranh nhi thiện thắng， bất ngôn nhi thiện ứng， bất triệu nhi tự lai， xiển nhiên nhi thiện mưu。 thiên võng khôi khôi， sơ nhi bất thất。","pinyinReading":"tiān zhī dào， bù zhēng ér shàn shèng， bù yán ér shàn yìng， bù zhào ér zì lái， chǎn rán ér shàn móu。 tiān wǎng huī huī， shū ér bù shī。","translation":"Đạo trời không tranh mà giỏi thắng, không nói mà giỏi đáp, không gọi mà tự đến, thong thả mà giỏi mưu tính. Lưới trời lồng lộng, thưa mà không sót.","textSimplified":"天之道，不争而善胜，不言而善应，不召而自来，繟然而善谋。天网恢恢，疏而不失。"},

  {"id":"snt_ch_work_ddk_74_1","chapterId":"ch_work_ddk_74","textTraditional":"民不畏死，奈何以死懼之？若使民常畏死，而為奇者，吾得執而殺之，孰敢？","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"dân bất úy tử， nại hà dĩ tử cụ chi？ nhược sử dân thường úy tử， nhi vi kỳ giả， ngô đắc chấp nhi sát chi， thục cảm？","pinyinReading":"mín bù wèi sǐ， nài hé yǐ sǐ jù zhī？ ruò shǐ mín cháng wèi sǐ， ér wéi qí zhě， wú dé zhí ér shā zhī， shú gǎn？","translation":"Dân không sợ chết, sao lại lấy cái chết dọa dân? Nếu khiến dân luôn sợ chết, kẻ làm điều kỳ quái, ta bắt giết đi, ai dám?","textSimplified":"民不畏死，奈何以死惧之？若使民常畏死，而为奇者，吾得执而杀之，孰敢？"},
  {"id":"snt_ch_work_ddk_74_2","chapterId":"ch_work_ddk_74","textTraditional":"常有司殺者殺。夫代司殺者殺，是謂代大匠斲。夫代大匠斲者，希有不傷其手矣。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thường hữu tư sát giả sát。 phù đại tư sát giả sát， thị vị đại đại tượng trác。 phù đại đại tượng trác giả， hi hữu bất thương kỳ thủ hĩ。","pinyinReading":"cháng yǒu sī shā zhě shā。 fú dài sī shā zhě shā， shì wèi dài dà jiàng zhuó。 fú dài dà jiàng zhuó zhě， xī yǒu bù shāng qí shǒu yǐ。","translation":"Thường có kẻ cai quản sự chết để giết. Thay kẻ cai quản sự chết mà giết, gọi là thay thợ cả đẽo gọt. Thay thợ cả mà đẽo, ít có ai không bị thương tay.","textSimplified":"常有司杀者杀。夫代司杀者杀，是谓代大匠斫。夫代大匠斫者，希有不伤其手矣。"},

  {"id":"snt_ch_work_ddk_75_1","chapterId":"ch_work_ddk_75","textTraditional":"民之飢，以其上食稅之多，是以飢。民之難治，以其上之有為，是以難治。民之輕死，以其上求生之厚，是以輕死。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"dân chi cơ， dĩ kỳ thượng thực thuế chi đa， thị dĩ cơ。 dân chi nan trị， dĩ kỳ thượng chi hữu vi， thị dĩ nan trị。 dân chi khinh tử， dĩ kỳ thượng cầu sinh chi hậu， thị dĩ khinh tử。","pinyinReading":"mín zhī jī， yǐ qí shàng shí shuì zhī duō， shì yǐ jī。 mín zhī nán zhì， yǐ qí shàng zhī yǒu wéi， shì yǐ nán zhì。 mín zhī qīng sǐ， yǐ qí shàng qiú shēng zhī hòu， shì yǐ qīng sǐ。","translation":"Dân đói vì bề trên thu thuế quá nhiều, nên đói. Dân khó trị vì bề trên can thiệp quá nhiều, nên khó trị. Dân coi nhẹ cái chết vì bề trên tham sống quá nhiều, nên coi nhẹ cái chết.","textSimplified":"民之饥，以其上食税之多，是以饥。民之难治，以其上之有为，是以难治。民之轻死，以其上求生之厚，是以轻死。"},
  {"id":"snt_ch_work_ddk_75_2","chapterId":"ch_work_ddk_75","textTraditional":"夫唯無以生為者，是賢於貴生。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"phù duy vô dĩ sinh vi giả， thị hiền ư quý sinh。","pinyinReading":"fú wéi wú yǐ shēng wéi zhě， shì xián yú guì shēng。","translation":"Chỉ có người không lấy sống làm mục đích, mới hơn kẻ tham sống.","textSimplified":"夫唯无以生为者，是贤于贵生。"},

  {"id":"snt_ch_work_ddk_76_1","chapterId":"ch_work_ddk_76","textTraditional":"人之生也柔弱，其死也堅強。草木之生也柔脆，其死也枯槁。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"nhân chi sinh dã nhu nhược， kỳ tử dã kiên cường。 thảo mộc chi sinh dã nhu thúy， kỳ tử dã khô cảo。","pinyinReading":"rén zhī shēng yě róu ruò， qí sǐ yě jiān qiáng。 cǎo mù zhī shēng yě róu cuì， qí sǐ yě kū gǎo。","translation":"Người lúc sống thì mềm yếu, lúc chết thì cứng đơ. Cỏ cây lúc sống thì mềm mại, lúc chết thì khô héo.","textSimplified":"人之生也柔弱，其死也坚强。草木之生也柔脆，其死也枯槁。"},
  {"id":"snt_ch_work_ddk_76_2","chapterId":"ch_work_ddk_76","textTraditional":"故堅強者死之徒，柔弱者生之徒。是以兵強則滅，木強則折。強大處下，柔弱處上。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"cố kiên cường giả tử chi đồ， nhu nhược giả sinh chi đồ。 thị dĩ binh cường tắc diệt， mộc cường tắc chiết。 cường đại xử hạ， nhu nhược xử thượng。","pinyinReading":"gù jiān qiáng zhě sǐ zhī tú， róu ruò zhě shēng zhī tú。 shì yǐ bīng qiáng zé miè， mù qiáng zé zhé。 qiáng dà chǔ xià， róu ruò chǔ shàng。","translation":"Cho nên cứng mạnh thuộc về chết, mềm yếu thuộc về sống. Vì thế binh mạnh thì bị diệt, cây cứng thì bị gãy. Cứng lớn ở dưới, mềm yếu ở trên.","textSimplified":"故坚强者死之徒，柔弱者生之徒。是以兵强则灭，木强则折。强大处下，柔弱处上。"},

  {"id":"snt_ch_work_ddk_77_1","chapterId":"ch_work_ddk_77","textTraditional":"天之道，其猶張弓歟？高者抑之，下者舉之；有餘者損之，不足者補之。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thiên chi đạo， kỳ do trương cung dư？ cao giả ức chi， hạ giả cử chi； hữu dư giả tổn chi， bất túc giả bổ chi。","pinyinReading":"tiān zhī dào， qí yóu zhāng gōng yú？ gāo zhě yì zhī， xià zhě jǔ zhī； yǒu yú zhě sǔn zhī， bù zú zhě bǔ zhī。","translation":"Đạo trời chẳng phải như giương cung sao? Cao thì kéo xuống, thấp thì nâng lên; thừa thì bớt đi, thiếu thì bù vào.","textSimplified":"天之道，其犹张弓欤？高者抑之，下者举之；有余者损之，不足者补之。"},
  {"id":"snt_ch_work_ddk_77_2","chapterId":"ch_work_ddk_77","textTraditional":"天之道，損有餘而補不足。人之道則不然，損不足以奉有餘。孰能有餘以奉天下？唯有道者。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thiên chi đạo， tổn hữu dư nhi bổ bất túc。 nhân chi đạo tắc bất nhiên， tổn bất túc dĩ phụng hữu dư。 thục năng hữu dư dĩ phụng thiên hạ？ duy hữu đạo giả。","pinyinReading":"tiān zhī dào， sǔn yǒu yú ér bǔ bù zú。 rén zhī dào zé bù rán， sǔn bù zú yǐ fèng yǒu yú。 shú néng yǒu yú yǐ fèng tiān xià？ wéi yǒu dào zhě。","translation":"Đạo trời bớt chỗ thừa bù chỗ thiếu. Đạo người thì không vậy, bớt chỗ thiếu để dâng chỗ thừa. Ai có thể lấy chỗ thừa dâng cho thiên hạ? Chỉ có người có Đạo.","textSimplified":"天之道，损有余而补不足。人之道则不然，损不足以奉有余。孰能有余以奉天下？唯有道者。"},
  {"id":"snt_ch_work_ddk_77_3","chapterId":"ch_work_ddk_77","textTraditional":"是以聖人為而不恃，功成而不處，其不欲見賢。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"thị dĩ thánh nhân vi nhi bất thị， công thành nhi bất xử， kỳ bất dục kiến hiền。","pinyinReading":"shì yǐ shèng rén wéi ér bù shì， gōng chéng ér bù chǔ， qí bù yù jiàn xián。","translation":"Vì thế thánh nhân làm mà không cậy, công thành mà không ở lại, không muốn phô bày sự giỏi giang.","textSimplified":"是以圣人为而不恃，功成而不处，其不欲见贤。"},

  {"id":"snt_ch_work_ddk_78_1","chapterId":"ch_work_ddk_78","textTraditional":"天下莫柔弱於水，而攻堅強者莫之能勝，以其無以易之。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"thiên hạ mạc nhu nhược ư thủy， nhi công kiên cường giả mạc chi năng thắng， dĩ kỳ vô dĩ dịch chi。","pinyinReading":"tiān xià mò róu ruò yú shuǐ， ér gōng jiān qiáng zhě mò zhī néng shèng， yǐ qí wú yǐ yì zhī。","translation":"Thiên hạ không gì mềm yếu bằng nước, nhưng công phá cứng mạnh thì không gì thắng được nước, vì không gì thay thế được nó."},
  {"id":"snt_ch_work_ddk_78_2","chapterId":"ch_work_ddk_78","textTraditional":"弱之勝強，柔之勝剛，天下莫不知，莫能行。是以聖人云：受國之垢，是謂社稷主；受國不祥，是為天下王。正言若反。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"nhược chi thắng cường， nhu chi thắng cương， thiên hạ mạc bất tri， mạc năng hành。 thị dĩ thánh nhân vân： thụ quốc chi cấu， thị vị xã tắc chủ； thụ quốc bất tường， thị vi thiên hạ vương。 chính ngôn nhược phản。","pinyinReading":"ruò zhī shèng qiáng， róu zhī shèng gāng， tiān xià mò bù zhī， mò néng xíng。 shì yǐ shèng rén yún： shòu guó zhī gòu， shì wèi shè jì zhǔ； shòu guó bù xiáng， shì wéi tiān xià wáng。 zhèng yán ruò fǎn。","translation":"Yếu thắng mạnh, mềm thắng cứng, thiên hạ không ai không biết mà không ai làm được. Vì thế thánh nhân nói: Chịu nhơ bẩn của nước là chủ xã tắc; chịu tai họa của nước là vua thiên hạ. Lời nói thẳng nghe như ngược đời.","textSimplified":"弱之胜强，柔之胜刚，天下莫不知，莫能行。是以圣人云：受国之垢，是谓社稷主；受国不祥，是为天下王。正言若反。"},

  {"id":"snt_ch_work_ddk_79_1","chapterId":"ch_work_ddk_79","textTraditional":"和大怨，必有餘怨，安可以為善？是以聖人執左契，而不責於人。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"hòa đại oán， tất hữu dư oán， an khả dĩ vi thiện？ thị dĩ thánh nhân chấp tả khế， nhi bất trách ư nhân。","pinyinReading":"hé dà yuàn， bì yǒu yú yuàn， ān kě yǐ wéi shàn？ shì yǐ shèng rén zhí zuǒ qì， ér bù zé yú rén。","translation":"Hòa giải oán lớn tất vẫn còn oán, sao có thể gọi là tốt? Vì thế thánh nhân giữ phần khế ước bên trái (phần cho vay) mà không đòi hỏi người.","textSimplified":"和大怨，必有余怨，安可以为善？是以圣人执左契，而不责于人。"},
  {"id":"snt_ch_work_ddk_79_2","chapterId":"ch_work_ddk_79","textTraditional":"有德司契，無德司徹。天道無親，常與善人。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"hữu đức tư khế， vô đức tư triệt。 thiên đạo vô thân， thường dữ thiện nhân。","pinyinReading":"yǒu dé sī qì， wú dé sī chè。 tiān dào wú qīn， cháng yǔ shàn rén。","translation":"Người có đức giữ khế ước, người vô đức lo thu thuế. Đạo trời không thân ai, thường giúp người thiện.","textSimplified":"有德司契，无德司彻。天道无亲，常与善人。"},

  {"id":"snt_ch_work_ddk_80_1","chapterId":"ch_work_ddk_80","textTraditional":"小國寡民，使有什伯之器而不用，使民重死而不遠徙。雖有舟輿，無所乘之；雖有甲兵，無所陳之。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"tiểu quốc quả dân， sử hữu thập bách chi khí nhi bất dụng， sử dân trọng tử nhi bất viễn tỉ。 tuy hữu chu dư， vô sở thừa chi； tuy hữu giáp binh， vô sở trần chi。","pinyinReading":"xiǎo guó guǎ mín， shǐ yǒu shí bó zhī qì ér bù yòng， shǐ mín zhòng sǐ ér bù yuǎn xǐ。 suī yǒu zhōu yú， wú suǒ chéng zhī； suī yǒu jiǎ bīng， wú suǒ chén zhī。","translation":"Nước nhỏ dân ít, dù có đồ dùng gấp mười gấp trăm cũng không dùng, khiến dân coi trọng cái chết mà không đi xa. Tuy có thuyền xe, không có chỗ đi; tuy có áo giáp binh khí, không có chỗ bày.","textSimplified":"小国寡民，使有什伯之器而不用，使民重死而不远徙。虽有舟舆，无所乘之；虽有甲兵，无所陈之。"},
  {"id":"snt_ch_work_ddk_80_2","chapterId":"ch_work_ddk_80","textTraditional":"使民復結繩而用之。甘其食，美其服，安其居，樂其俗。鄰國相望，雞犬之聲相聞，民至老死不相往來。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"sử dân phục kết thằng nhi dụng chi。 cam kỳ thực， mỹ kỳ phục， an kỳ cư， lạc kỳ tục。 lân quốc tương vọng， kê khuyển chi thanh tương văn， dân chí lão tử bất tương vãng lai。","pinyinReading":"shǐ mín fù jié shéng ér yòng zhī。 gān qí shí， měi qí fú， ān qí jū， lè qí sú。 lín guó xiāng wàng， jī quǎn zhī shēng xiāng wén， mín zhì lǎo sǐ bù xiāng wǎng lái。","translation":"Khiến dân quay về thắt nút dây thừng mà dùng. Ăn thấy ngon, mặc thấy đẹp, ở thấy yên, tục thấy vui. Nước láng giềng nhìn thấy nhau, tiếng gà chó nghe thấy nhau, dân đến già chết không qua lại.","textSimplified":"使民复结绳而用之。甘其食，美其服，安其居，乐其俗。邻国相望，鸡犬之声相闻，民至老死不相往来。"},

  {"id":"snt_ch_work_ddk_81_1","chapterId":"ch_work_ddk_81","textTraditional":"信言不美，美言不信。善者不辯，辯者不善。知者不博，博者不知。","sentenceOrder":1,"paragraphGroup":1,"hanVietReading":"tín ngôn bất mỹ， mỹ ngôn bất tín。 thiện giả bất biện， biện giả bất thiện。 tri giả bất bác， bác giả bất tri。","pinyinReading":"xìn yán bù měi， měi yán bù xìn。 shàn zhě bù biàn， biàn zhě bù shàn。 zhī zhě bù bó， bó zhě bù zhī。","translation":"Lời chân thật thì không hoa mỹ, lời hoa mỹ thì không chân thật. Người giỏi thì không tranh cãi, người tranh cãi thì không giỏi. Người biết thì không uyên bác, người uyên bác thì không biết.","textSimplified":"信言不美，美言不信。善者不辩，辩者不善。知者不博，博者不知。"},
  {"id":"snt_ch_work_ddk_81_2","chapterId":"ch_work_ddk_81","textTraditional":"聖人不積，既以為人己愈有，既以與人己愈多。","sentenceOrder":2,"paragraphGroup":2,"hanVietReading":"thánh nhân bất tích， ký dĩ vi nhân kỷ dũ hữu， ký dĩ dữ nhân kỷ dũ đa。","pinyinReading":"shèng rén bù jī， jì yǐ wéi rén jǐ yù yǒu， jì yǐ yǔ rén jǐ yù duō。","translation":"Thánh nhân không tích trữ, đã vì người thì mình càng có, đã cho người thì mình càng nhiều.","textSimplified":"圣人不积，既以为人己愈有，既以与人己愈多。"},
  {"id":"snt_ch_work_ddk_81_3","chapterId":"ch_work_ddk_81","textTraditional":"天之道，利而不害；聖人之道，為而不爭。","sentenceOrder":3,"paragraphGroup":2,"hanVietReading":"thiên chi đạo， lợi nhi bất hại； thánh nhân chi đạo， vi nhi bất tranh。","pinyinReading":"tiān zhī dào， lì ér bù hài； shèng rén zhī dào， wéi ér bù zhēng。","translation":"Đạo trời, lợi mà không hại; đạo thánh nhân, làm mà không tranh.","textSimplified":"天之道，利而不害；圣人之道，为而不争。"},
];

